%  end
% --- Executes on button press in Run_AQP.
% =========================================================================
% [DELEGATED, Aug 2026]  This callback no longer holds the AQP run inline.
% The ~305-line body that used to live here was extracted, together with its
% full 256-function dependency closure, into the standalone file Run_AQP.m.
% This stub now does three things and nothing else:
%     1. forwards (hObject, eventdata, handles) to Run_AQP,
%     2. takes back the UPDATED handles struct and commits it with guidata,
%     3. restores the working directory if the run aborts part-way.
%
% Why handles must be returned rather than mutated in place: the graphics
% widgets inside handles (CurStatus, sNumResults, cPP1, ...) are handle
% objects, so the pipeline's edits to them are visible without any return
% value. But Run_AQP also adds PLAIN STRUCT FIELDS - OUT_Cmp_Results,
% out_SbS, hf_AQP - and MATLAB passes structs BY VALUE. Those fields exist
% only on Run_AQP's local copy until they are handed back here.
%
% The original inline body is preserved verbatim immediately below as
% Run_AQP_Callback_legacy_inline, and is used automatically as a fallback if
% Run_AQP.m is not on the path. All helper functions it needs remain in this
% file untouched, since other callbacks still use them.
% =========================================================================
function Run_AQP_Callback(hObject, eventdata, handles)
% hObject    handle to Run_AQP (see GCBO)
% eventdata  reserved - to be defined in a future version of MATLAB
% handles    structure with handles and user data (see GUIDATA)

    cwd_before = pwd;                 % Run_AQP cd's into TMP_AQP; see cleanup below

    % ---- PRE-FLIGHT: pin dependencies to the PATH before anything cd's ----
    % The pipeline cd's into TMP_AQP within the first few statements and then
    % keeps cd'ing (TMP_AQP-MGs, Tmst_Ptrg_XRS, ...). Anything that is merely
    % in the CURRENT FOLDER rather than on the MATLAB SEARCH PATH disappears
    % the moment that happens, and the failure surfaces hundreds of lines
    % later as "Undefined function 'ssds' for input arguments of type 'char'".
    % Resolving here - while we are still in the launch folder - and adding
    % the owning folders to the path makes the run cd-proof.
    % [MERGED 25 Aug 2026] 'Run_AQP' removed from the REQUIRED list - it is a
    % local function of this file now, and local_pin_deps_to_path resolves
    % names with which(), which does not see local functions. Leaving it in
    % would have made the pre-flight report Run_AQP as missing and abort every
    % run. No REQUIRED dependency is external any more, so the required pin is
    % a no-op; the OPTIONAL pin below still does its job.
    % was: if ~local_pin_deps_to_path({'Run_AQP'}), return, end

    % ---- OPTIONAL deps: pin if present, warn (never abort) if absent -----
    % [OPEN ITEM 1, 20 Aug 2026] svmtrain_MEX / svmpredict_MEX are reached only through
    % SVR_inside_PLS_predict_ONLY and the RUN_SVM_* classifiers, all of which
    % sit behind `if run_SVR_yes`. Pinning them as REQUIRED would have been a
    % regression: a PLS-only run on a machine without libsvm would stop dead
    % at the pre-flight instead of completing as it does today.
    local_pin_deps_to_path({'svmtrain_MEX','svmpredict_MEX'}, 'optional');

    % [MERGED 25 Aug 2026] Run_AQP is now a LOCAL function of this file; see
    % the note on the Load_DS guard above. Pinned false.
    if false   % was: exist('Run_AQP','file') ~= 2
        % ---- fallback: Run_AQP.m not on the path, use the archived body ----
        warning('AQP_gui:Run_AQP_missing', ...
                ['Run_AQP.m was not found on the MATLAB path. ', ...
                 'Falling back to the archived inline body ', ...
                 '(Run_AQP_Callback_legacy_inline).']);
        Run_AQP_Callback_legacy_inline(hObject, eventdata, handles);
        return
    end

    % ---- delegate ------------------------------------------------------
    try
        [handles, OUT_Cmp_Results] = Run_AQP(hObject, eventdata, handles);
    catch ME
        % leave the user where they started, not stranded inside TMP_AQP
        try
            cd(cwd_before);
        end
        try
            handles.CurStatus.String = 'AQP run FAILED - see command window';
        end
        try
            guidata(hObject, handles);   % keep whatever partial state exists
        end
        disp(getReport(ME,'extended','hyperlinks','on'));
        errordlg({'The AQP run did not complete.'; ''; ME.message}, ...
                 'Run AQP failed', 'modal');
        return
    end

    % ---- commit the returned struct ------------------------------------
    % Run_AQP already calls guidata(gcbo,handles) when invoked from a
    % callback, but committing against hObject here is explicit, idempotent,
    % and also correct when this function is driven programmatically.
    if ~isempty(hObject) && isgraphics(hObject)
        guidata(hObject, handles);
    end

    % ---- Compare Results button state ----------------------------------
    % [CMP BUTTON STATE, 22 Aug 2026] belt-and-braces: Run_AQP.m refreshes
    % the button itself, but an older Run_AQP.m on the path would not.
    try
        AQP_gui_merged__CmpR_update_Cmp_Results_button(handles);
    end

    % ---- post-run housekeeping -----------------------------------------
    if isempty(OUT_Cmp_Results)
        warning('AQP_gui:no_results', ...
                'Run_AQP returned no OUT_Cmp_Results structure.');
    end
    if ~strcmp(pwd, cwd_before)
        cd(cwd_before);               % Run_AQP normally does this itself
    end
end


% =========================================================================
% [DELEGATED helper] Resolve each required dependency from the CURRENT folder
% and put its owning folder on the MATLAB search path, so the run survives the
% cd into TMP_AQP. Returns false (after an errordlg) if anything is missing.
% =========================================================================
% the following function -->local_pin_deps_to_path  was added by Claude on Aug 19, 2026 too
function ok = local_pin_deps_to_path(names, mode)
% [AMENDED, 20 Aug 2026] second argument added.
%   mode = 'required' (default) - a missing name aborts the run.
%   mode = 'optional'           - a missing name only warns.
%
% Why the tier exists: the SVR/SVM branches are gated by `run_SVR_yes`, so
% svmtrain_MEX and svmpredict_MEX are needed on SOME runs only. Listing them
% as required would abort a perfectly valid PLS-only run on any machine that
% has no libsvm build. Listing them as optional still puts their folder on
% the path when they ARE present - which is the whole point of the pre-flight,
% since the pipeline cd's away from the launch folder almost immediately.
    if nargin < 2 || isempty(mode)
        mode = 'required';
    end
    required = ~strcmpi(mode,'optional');

    ok      = true;
    missing = {};

    for k = 1:numel(names)
        nm = names{k};

        p = which(nm);                          % honours the current folder
        if isempty(p) || ~exist(p,'file')
            p = which([nm '.m']);               % classdef fallback
        end
        if isempty(p) || ~exist(p,'file')
            missing{end+1} = nm;  %#ok<AGROW>
            continue
        end

        fldr = fileparts(p);
        if isempty(fldr), continue, end

        % case-insensitive membership test on Windows
        haystack = [pathsep path pathsep];
        needle   = [pathsep fldr pathsep];
        if ispc
            haystack = lower(haystack);
            needle   = lower(needle);
        end
        if isempty(strfind(haystack, needle))   %#ok<STREMP> % R2016b compatible
            addpath(fldr);
            fprintf('AQP_gui: added to MATLAB path -> %s   (required by %s)\n', fldr, nm);
        end
    end

    if ~isempty(missing)
        if required
            ok  = false;
            msg = [{'Cannot start the AQP run - these are not on the path:'}; {''}; ...
                   missing(:); {''}; ...
                   {'Put them in the launch folder or use addpath, then try again.'}];
            errordlg(msg, 'Missing dependency', 'modal');
            disp(msg);
        else
            % [AMENDED, 20 Aug 2026] optional tier: warn, do not block. The branch that
            % actually needs these will still fail if it is reached, but a run
            % that never enters it now proceeds as it always did.
            warning('AQP_gui:optional_dep_missing', ...
                    ['Optional dependency not on the path: %s. ', ...
                     'Runs that do not enter the SVR/SVM branch are unaffected; ', ...
                     'if run_SVR_yes is set, that branch will fail when reached.'], ...
                    strjoin(missing(:).', ', '));
        end
    end
end


