function out_PP_RS=AQP_gui_merged__PP_on_RawSpectra(PP_methods,inp4PP_on_RS)
path_P=AQP_gui_merged__tmp_folder_rm_mk('TMP_PP_AQP',pwd);
path_prev=pwd;
cd(path_P);

inpPP.PP_methods=PP_methods;

pathfname_XRS=AQP_gui_merged__get_OnlyOne_AT(inp4PP_on_RS.path_Tmst_Ptrg_XRS);
out_PP_XRS=AQP_gui_merged__pretreat_preprocess_RawSpectra_pp1_pp2_AT_TP(pathfname_XRS,inpPP);
out_PP_RS.pathfname_PP_XRS=[pwd,'\',out_PP_XRS.fname_new];
%%%%%%%%%%%%%
path_P_Val=AQP_gui_merged__tmp_folder_rm_mk('Val',pwd);
pathfname_Val=AQP_gui_merged__get_OnlyOne_AT(inp4PP_on_RS.path_Tmst_Ptrg_Val);
cd(path_P_Val);
out_PP_Val=AQP_gui_merged__pretreat_preprocess_RawSpectra_pp1_pp2_AT_TP(pathfname_Val,inpPP);
out_PP_RS.pathfname_PP_Val=[pwd,'\',out_PP_Val.fname_new];

%%%%%%%%%%%%%%
% deal with "pathfname_MGs_PP_XSmst"
cd(path_P);

path_PP_XSmst=AQP_gui_merged__tmp_folder_rm_mk('PP_XSmst',pwd);

pathfname_XSmst=inp4PP_on_RS.pathfname_MGs_PP_XSmst;

cd(path_PP_XSmst);

out_PP_XSmst=AQP_gui_merged__pretreat_preprocess_RawSpectra_pp1_pp2_AT_TP(pathfname_XSmst,inpPP);
out_PP_RS.pathfname_MGs_PP_XSmst=[pwd,'\',out_PP_XSmst.fname_new];



%%%%%%%%%%%%%%%
cd(path_prev);

if false
    
    figure;hold on;
    LRS=load(pathfname_Val);
    plot(LRS.RawSpectra.Tset','b-O');
    plot(LRS.RawSpectra.Pset','r-*');
    title('RawSpectra')
    
    figure;hold on;
    LPP=load(outPP.fname_new);
    plot(LPP.Atrainpk','c->');
    plot(LPP.Apred','m-+');
    title(PP_methods.pp1)
    
end


disp('done PP on RS')
end

