function      out_XferPP=AQP_gui_merged__Xfer_on_PP(cCabXfer_scheme,inp4XferPP)

path_prev=pwd;

LINP=AQP_gui_merged__load_local_try('C:\work\JDSU\CabXfer_Results_Review\meta_AQDAP\INP_wo_handles.mat');
INP=LINP.INP;
INP=rmfield(INP,'cCabXfer_scheme');
INP=rmfield(INP,'cXM_Slct_scheme');
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
INP.pathfnameTP4Val=inp4XferPP.pathfname_PP_Val;
INP.TP_includeTrn_Yes=1; % default setting copied from CabXferLite
