path_CabX=inp4XferPP.path_PP_XRS;

INP.pathfname_MGs_PP_XSmst=inp4XferPP.pathfname_MGs_PP_XSmst;

INP.inp4AQP= inp4XferPP.inp4AQP;
OUT_Xfer=AQP_gui_merged__BatchRun_CabXfer_Siesler48_MLtool(path_CabX,INP);

out_XferPP.INP=INP;
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% carry "Model_GLS" to outside of internal functions CabXfer_Siesler48_MLtool
out_XferPP.Model_GLS=OUT_Xfer.Model_GLS;
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% move XRS and Val to their own folder
cd([pwd,'\',INP.newpath_TMP_Cabxfer]);

 [clistfile nfile]=AQP_gui_merged__fdir_wildcard_ext_wPath(pwd,'Atrainpketc_','mat');
 loc_Val=find(cellfun(@(x) ~isempty(strfind(AQP_gui_merged__fileparts_name_ext(x),'Val')),clistfile));
 loc_XRS=find(cellfun(@(x) isempty(strfind(AQP_gui_merged__fileparts_name_ext(x),'Val')),clistfile));
 
path_XRS=AQP_gui_merged__tmp_folder_rm_mk('XRS',pwd);
copyfile(clistfile{loc_XRS},path_XRS);
delete(clistfile{loc_XRS});
 
path_Val=AQP_gui_merged__tmp_folder_rm_mk('Val',pwd);
copyfile(clistfile{loc_Val},path_Val);
delete(clistfile{loc_Val});


cd(path_prev);

out_XferPP.pathfname_XRS=AQP_gui_merged__get_OnlyOne_AT(path_XRS)
out_XferPP.pathfname_Val=AQP_gui_merged__get_OnlyOne_AT(path_Val)


disp('done Xfer_on_PP')
end

