            else
                %         plot(allRMSE_PPj,'color',color_CH(scolor_PP(jLine)),'marker',smarker_DF(kDF),'linewidth',2,'markersize',12);
                plot(allRMSE_PPj,'color',AQP_gui_merged__color_CH(scolor_PP(jLine)),'marker',AQP_gui_merged__marker_CH(smarker_PP(jLine)),'linewidth',2,'markersize',12);
            end
        end
        
    end
