        AQP_gui_merged__CmpR_set_XTickLabel_wrap(gca,cLegendLoop,-45,8,inp4XTL);
        stit_call_XLabel_Grids=call_XLabel_Grids{1};
    else
%         rotate_xticklabel_anydeg(strrep(call_XLabel_Grids,'_','\_'),-45,10);
