        AQP_gui_merged__CmpR_set_XTickLabel_wrap(gca,call_XLabel_Grids,-45,10,inp4XTL);
        stit_call_XLabel_Grids='';
    end
    
    ylabel('RMSEP')
    
    % stit=strrep(find_keyword_between_markers( find_lastNfolder(  InpBR.path_CS_Val,2),'','\'),'_','\_');
    try
        stit=strrep(AQP_gui_merged__find_keyword_between_markers( AQP_gui_merged__find_lastNfolder(  InpBR.pathfname_UDM,3),'','\'),'_','\_');
    catch
        try
            stit=strrep(AQP_gui_merged__find_keyword_between_markers( AQP_gui_merged__find_lastNfolder(  InpBR.path_CS_Val,2),'','\'),'_','\_');
        catch
            stit=strrep( AQP_gui_merged__find_lastNfolder(  InpBR.path_XLSX,1),'_','\_');
        end
    end
    
    if length(cPP1)==1
