catch
    Clsfr_short_GM='SVM_Linear_wDecVal_APs';  % default set to this
end
switch Clsfr_short_GM
    case {'Linear_wDecVal_APs','SVM' , 'SVM_Linear_wDecVal_APs' , 'SVM_linear_wDecVal_APs'}
        %+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
        handles4Clsfr.L=L0_auto;
