        all_predcls= out4Clsfr.predcls;
        loc_misP=find(all_predcls~=L0.AclassinfoP);
        %+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
     case {'SVM_OVA_RBF_wDecVal', 'ova_rbf_wDecVal'}
