    all_out_eaBR=[all_out_eaBR ;  out_eaBR ];
    %=============================================================================================================
    %=============================================================================================================
    %++++++++++++++++++++++++++++++++++++++++++++++++++++
   if ~isempty( out_eaBR.LAT_rq_sT)
           inp_iqcn_kt.corename=['{',AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_ext(pfn_GM_only),'Atrainpketc_','_nvar'),'[WinCls1st-',inp4eaBR.winner_clistclslabel ,']','}'];    % save sd_iqcn_kt based on kt (or WinCls1st ) approach , end of July, 2024
