%===================================

%----------------------------------------------------
try
    nD=inp.nD;
catch
    nD=2;
end
try
 rand_cov_yes  = inp.rand_cov_yes;
catch
  rand_cov_yes=1;  
end


%====================================================

allh=[];
allp=[];
allh_alt=[];
allp_alt=[];

all_mean_sqrt_MD2_X1=[];
all_mean_sqrt_MD2_X=[];
all_mean_sqrt_MD2_XP_in_range=[];
for irun=1:inp.Nrun
    close all
    [h,p , mean_sqrt_MD2_X1 , mean_sqrt_MD2_X ,h_alt,p_alt,out_irun ] = AQP_gui_merged__test_Mahal_Rolling_PCA_Random_covariance_matrix( bz,dev_X1 ,inp );
    allh=[allh;h  ];
    allp=[allp;p];
    all_mean_sqrt_MD2_X1=[all_mean_sqrt_MD2_X1; mean_sqrt_MD2_X1];
    all_mean_sqrt_MD2_X=[all_mean_sqrt_MD2_X; mean_sqrt_MD2_X];
    allh_alt=[allh_alt;h_alt  ];
    allp_alt=[allp_alt;p_alt];
    %----------------------------------------------
   all_mean_sqrt_MD2_XP_in_range=[all_mean_sqrt_MD2_XP_in_range; out_irun.mean_sqrt_MD2_XP ]; % study current settings in rPCA with ttest approach
end
%----------------------------------------------------
avg_sqrt_MD2_X1=mean(all_mean_sqrt_MD2_X1);
avg_sqrt_MD2_X=mean(all_mean_sqrt_MD2_X);
%------------------------------------------------------
% study current settings in rPCA with ttest approach
MD_XP_in_range=all_mean_sqrt_MD2_XP_in_range(~isnan(all_mean_sqrt_MD2_XP_in_range));
figure;hold on;set(gcf,'position',1000*[ 0.1937    0.1787    1.5940    0.5731  ]);
plot(all_mean_sqrt_MD2_X1,'k-*');
AQP_gui_merged__plot_hline(mean(all_mean_sqrt_MD2_X1),'c');
plot(find(~isnan(all_mean_sqrt_MD2_XP_in_range)),MD_XP_in_range,'bO','linewidth',2);
AQP_gui_merged__title_usF(['number of in range MD_XP = ',num2str(length(MD_XP_in_range ))]);
AQP_gui_merged__title_add(gca,['Mean of all sqrt_MD2_X1 = ',AQP_gui_merged__roundns(avg_sqrt_MD2_X1,2)]);

%--------------------------------------------------------------
figure;hold on;set(gcf,'position',1000*[  0.3886    0.2689    1.2817    0.5266  ]);
log_allp=log(allp);
hpp=plot(log_allp,'k-*');
ylabel('all p value');
set(gca,'YLim',[min(log(allp))  0]);
% yyaxis right
% hph=plot(allh,'r-diamond');
% ylabel('H');
loc_H_0=find(~allh);
loc_H_1=find(allh);
%----------------------------------
loc_H_0_alt=find(~allh_alt);
loc_H_1_alt=find(allh_alt);


%----------------------------------
plot(loc_H_0,log_allp( loc_H_0),'gO','linewidth',2);
plot(loc_H_1,log_allp( loc_H_1),'rO','linewidth',2);
p_value_calc=length(loc_H_0)/inp.Nrun;
sPSS=['Percentage of Blocks Reach Steady State = ',AQP_gui_merged__roundns(p_value_calc*100,2),'%'];
% legend([hpp hph],{'all p value','H'});
AQP_gui_merged__title_usF( sPSS);
%------------------------------------------------------
p_value_calc_alt=length(loc_H_0_alt)/inp.Nrun;
sPSS_alt=['Percentage of Blocks Reach Steady State ( ttest2 on MD2 Directly) = ',AQP_gui_merged__roundns(p_value_calc_alt*100,2),'%'];
AQP_gui_merged__title_add(gca,sPSS_alt);

%-------------------------------------------------------

% dev_X1
AQP_gui_merged__title_add(gca,['dev_X1 = ',AQP_gui_merged__roundns(dev_X1,3)]);
AQP_gui_merged__title_add(gca,['Block Size (bz) = ',AQP_gui_merged__roundns(bz,0)]);

AQP_gui_merged__title_add(gca,['Mean of all sqrt_MD2_X = ',AQP_gui_merged__roundns(avg_sqrt_MD2_X,2)]);
AQP_gui_merged__title_add(gca,['Mean of all sqrt_MD2_X1 = ',AQP_gui_merged__roundns(avg_sqrt_MD2_X1,2)]);
AQP_gui_merged__title_add(gca,['dev of Mean of all sqrt_MD2_X1 vs X = ',AQP_gui_merged__roundns(avg_sqrt_MD2_X1-avg_sqrt_MD2_X,2)]);
AQP_gui_merged__title_add(gca,['nD = ',AQP_gui_merged__roundns(nD,0)]);
if ~rand_cov_yes
    AQP_gui_merged__title_add(gca,['rand_cov_yes = ',AQP_gui_merged__roundns(rand_cov_yes,0),' (Uniform Covariance)']);
else
     AQP_gui_merged__title_add(gca,['rand_cov_yes = ',AQP_gui_merged__roundns(rand_cov_yes,0),' (Random Hetero Covariance)']);
end
%----------------------------------------------
out.p_value_calc=p_value_calc;


%----------------------------------------------
AQP_gui_merged__done_with_this_function;
end


