function out=AQP_gui_merged__find_MatchConc_1stUniqueSampleNameOnly(x,allC_T,allSampleName_T)
allSN=allSampleName_T(allC_T==x);
qSN=unique(allSN);
if ~isempty(qSN)
out=qSN{1};
else
   error('no match found in find_MatchConc_1stUniqueSampleNameOnly') 
end
end

function out=CabXfer_Siesler48_MLtool__isKSpick(x,Conc_KSpick)
if length(find(Conc_KSpick==x.Conc))==0
out=false;
elseif length(find(Conc_KSpick==x.Conc))==1
    
    out=true;
else
    error('more than one match found ')
end
end

