%% ----- from KennardStone.m ------------------------------------------------
function [idxTrn, idxRef] = AQP_gui_merged__KennardStone( mdY, nTrn)

% INPUT:
% mdY:          Spectra matrix
% Trn:          Number of Transfer Spectra to select
% 
% OUTPUT:
% idxTrn:       Indices for transfer spectra selected from spectra matrix mdY
% idxRef:       Indices for reference spectra selected from the spectra matrix mdY
%
% DESCRIPTION:
%       Calculates the index vectors to splits the spectra matrix 
%       mdY into transfer and reference set
if nTrn==1 | nTrn==2
    
    if nTrn==1
        error('nTrn must be at least 2')
    else
        sel = kennardstone(mdY, nTrn);
        idxTrn=find(sel==1);
        idxRef=find(sel~=1);
    end
    
    
else
    
    [mY, nY] = size( mdY );
    idxTrn = zeros( nTrn, 1 );
    mdYorg = mdY;
    
    [ dummy, idxTrn1 ] = min( AQP_gui_merged__SpcDistance( mean( mdY),  mdY ) );
    idxTrn(1) = idxTrn1;
    mdY( idxTrn1, : ) = NaN;
    
    [dummy, idxTrn2]= max( AQP_gui_merged__SpcDistance( mdY(idxTrn(1),:), mdY) );
    idxTrn(2) = idxTrn2;
    mdY( idxTrn2, : ) = NaN;
    
    for iTrn = 3:nTrn
        mdDist  = AQP_gui_merged__SpcDistance( mdY, mdYorg(idxTrn(1:iTrn-1),:) );
        vdMinNN = min( mdDist );
        [dummy idxMaxNN] = max( vdMinNN );
        idxTrn( iTrn ) = idxMaxNN;
        mdY( idxMaxNN, : ) = NaN;
    end
    
    idxRef = [1:mY]';
    idxRef( idxTrn ) = [];
    
    idxTrn = sort( idxTrn );
    idxRef = sort( idxRef );
    q = 0;
end
end


