%                     else
                    outPLS_TselfP_iPf=AQP_gui_merged__PLS_Tcv(X_iAna_T_Tcv,Y_iAna_T_Tcv,cSampleName_T_Tcv,inp4TselfP);  % new and fixed
%                     end
                    %*********************************************************
