function [X_iAna Y_iAna  cSampleName]=AQP_gui_merged__PLS_inside_PLS_predict_ONLY_MLtool__saConc2XY(saConc,AnaName)
idx_CurAna= arrayfun(@(x) strcmp(x.clsname,AnaName),saConc);
X_iAna=cell2mat(arrayfun(@(x) x.Atrainpk, saConc(idx_CurAna),'un',0));
Y_iAna=cell2mat(arrayfun(@(x) repmat(x.Conc,[length(x.Atrainpk(:,1)) 1]), saConc(idx_CurAna),'un',0));
cSampleName=AQP_gui_merged__cell_unwrap(arrayfun(@(x) repmat({x.SampleName},[length(x.Atrainpk(:,1)) 1]), saConc(idx_CurAna),'un',0));
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function out=AQP_gui_merged__PLS_inside_PLS_predict_ONLY_MLtool__isKSpick(x,Conc_KSpick)
if length(find(Conc_KSpick==x.Conc))==0
out=false;
elseif length(find(Conc_KSpick==x.Conc))==1
    
    out=true;
else
    error('more than one match found ')
end
end


% else
%     out.RMSE_SVR=NaN;
%     out.CV_SVR=NaN;


