function OUT_Regressor=AQP_gui_merged__PLS_on_Xfer_PP_or_PP_Xfer(path_X_P_XRS,path_X_P,inp4PLS_2DF)
% typically called by --> AutoQuant_DA_pipeline
% this function will call SVR_PLS_Opm_by_Testset_then_AppliedToPset_MLtool
%--------------------------------------------------------------------------------------------------------
% fix some kind of bug that cause no TP dataset will be found even though Val set does exist, Jan 3, 2023
% originally inside AutoQuant_DA_pipeline, now is an independent function
% this function will call SVR_PLS_Opm_by_Testset_then_AppliedToPset_MLtool
%======================================
% add following Nov 7, 2020
% % this is the case that there in Only CS exist
% however when Only CS exist and there is no Val, there should be
% two files inside this folder but only one of them have '{CS-ONLY}'
%------------------------------------------------------------------------------------------
% fix some kind of bug that cause no TP dataset will be found even though Val set does exist, Jan 3, 2023
% use char not cell here for  inp4PLS.pathfnameTP4Val  !!! Jan 4, 2023
%------------------------------------------------------------------------------------------
% this is the case that there is Only CS exist and use "cell" not "char" in this situation, Jan 4, 2023 !!!
% tested by --> C:\work\JDSU\Test_AQP_PowerUser\Siesler48_S1_T375_only-CS
%------------------------------------------------------------------------------------------
% deal with only CS+XRS exist but woVal, Jan 4, 2023
%------------------------------------------------------
%------------------------------------------------------------------------------------------
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    pathTP=path_X_P_XRS;
    %%%%%%%%%%%%%%%%%%%%%%%%%%%
%     Lip=load('C:\work\JDSU\CabXfer_Results_Review\meta_AQDAP\inp4PLS.mat');
%     inp4PLS=Lip.inp4PLS;
try
    L4Ana=load(AQP_gui_merged__get_OnlyOne_AT(path_X_P_XRS));
    inp4PLS.cList_Ana_to_Run_PLS={L4Ana.PLS.Tset.saConc(1).clsname};
catch
    try
        L4Ana=load(AQP_gui_merged__get_OnlyOne_AT(path_X_P));                 % when both CS and Val exist, there should be only one file inside this folder
    catch
        % however when Only CS exist and there is no Val, there should be
        % two files inside this folder but only one of them have '{CS-ONLY}'
        [clistfilename_out_CSonly, nfile_out_CS_only]=    AQP_gui_merged__fdir_wildcard_ext_wPath(path_X_P ,'{CS-ONLY}','mat');
        if  nfile_out_CS_only==1
            L4Ana=load(clistfilename_out_CSonly{1});
        end
        %-----------------------------------------------------------------------------------------------------------
        % deal with only CS+XRS exist but woVal, Jan 4, 2023
        if nfile_out_CS_only==0
            [clistfilename_out_CS_XRS_only, nfile_out_CS_XRS_only]=    AQP_gui_merged__fdir_wildcard_ext_wPath(path_X_P ,'wAT2RS_For_PRO','mat');% deal with only CS+XRS exist but woVal, Jan 4, 2023
            if nfile_out_CS_XRS_only==1
            L4Ana=load(clistfilename_out_CS_XRS_only{1});
            end
        end
        %-----------------------------------------------------------------------------------------------------------
    end
    inp4PLS.cList_Ana_to_Run_PLS={L4Ana.PLS.Tset.saConc(1).clsname};

end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    [clistfile_X_P_Val nfile_X_P_Val]=AQP_gui_merged__fdir_wildcard_ext_wPath([path_X_P],'Atrainpketc_','mat');
    if length(clistfile_X_P_Val)==1
        inp4PLS.pathfnameTP4Val=clistfile_X_P_Val{1};                                                                                                               % use char not cell here for  inp4PLS.pathfnameTP4Val  !!! Jan 4, 2023
    elseif nfile_X_P_Val>=2                                                                                                                                                          % fix this to deal with CS-ONLY case, Jan 4, 2023
        %--------------------------------------------------------------------------------------------------------------------------------------------------------
        % this is the case that there is Only CS exist and use "cell" not "char" in this situation, Jan 4, 2023 !!!
        % tested by --> C:\work\JDSU\Test_AQP_PowerUser\Siesler48_S1_T375_only-CS
        %
        %
        inp4PLS.pathfnameTP4Val= clistfile_X_P_Val(  AQP_gui_merged__strfind_cstr('{CS-ONLY}', clistfile_X_P_Val));                                            % this is the case that there is Only CS exist and use "cell" not "char" in this situation, Jan 4, 2023 !!!
        %----------------------------------------------------------------------------------------------------------------------------------------------------------
        % fix some kind of bug that cause no TP dataset will be found even though Val set does exist, Jan 3, 2023
        % if isempty(inp4PLS.pathfnameTP4Val) && ~isempty(strfind(  clistfile_X_P_Val{1} ,'for-AAQP'   ))                                          % fix some kind of bug that cause no TP dataset will be found even though Val set does exist, Jan 3, 2023
        if isempty(inp4PLS.pathfnameTP4Val) && ~isempty(clistfile_X_P_Val(  AQP_gui_merged__strfind_cstr('for-AAQP', clistfile_X_P_Val)))
            inp4PLS.pathfnameTP4Val=clistfile_X_P_Val{ AQP_gui_merged__strfind_cstr('for-AAQP', clistfile_X_P_Val)};                                                     % use char not cell here for  inp4PLS.pathfnameTP4Val  !!! Jan 4, 2023
        end
        %-----------------------------------------------------------------------------------------------------------------------------------------------------------
    else
        error('something wrong with clistfile_X_P_Val')
    end
     %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     
     if iscell(inp4PLS_2DF.CurUDMas)&& length(inp4PLS_2DF.CurUDMas)==1
     inp4PLS_2DF.CurUDMas=inp4PLS_2DF.CurUDMas{1};
     elseif ischar(inp4PLS_2DF.CurUDMas)
         disp('continue')
     else
         error('not ready to handle the datatype of inp4PLS_2DF.CurUDMas')
     end
     
     switch inp4PLS_2DF.CurUDMas
         
         case 'woUDM' 
             
             if strcmp( inp4PLS_2DF.CurTcvModelParaOpmScheme,'User-Pick')
                 inp4PLS_2DF.ModelPara_Opm_Scheme=inp4PLS_2DF.CurTcvModelParaOpmScheme;  % updated by CH, Nov 22, 2019
             else
                 inp4PLS_2DF.ModelPara_Opm_Scheme='ModelParaOpmBy-Tcv'; % 'woUDM' can only run with Tcv
             end
         %%% updating XRS  
         if ~isempty(inp4PLS_2DF.sd_CS_Val_orig)
             sd_XRS_folder_Cur=AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(pathTP));
             
             sd_CS_XRS4woUDM=AQP_gui_merged__ssds_gt(inp4PLS_2DF.sd_CS_Val_orig,AQP_gui_merged__P2T(sd_XRS_folder_Cur));
             
             
             path_prev=pwd;
             delete(AQP_gui_merged__get_OnlyOne_AT(pathTP));
             cd(pathTP);
             AQP_gui_merged__saveAT(sd_CS_XRS4woUDM);
             cd(path_prev);
             %%% updating Val
             sd_CS_Val4woUDM=AQP_gui_merged__ssds_gt(inp4PLS_2DF.sd_CS_Val_orig,AQP_gui_merged__P2T(AQP_gui_merged__ssds(inp4PLS.pathfnameTP4Val)));
             delete(inp4PLS.pathfnameTP4Val);
             cd(fileparts(inp4PLS.pathfnameTP4Val));
             AQP_gui_merged__saveAT(sd_CS_Val4woUDM);
             inp4PLS.pathfnameTP4Val=AQP_gui_merged__get_OnlyOne_AT(pwd);% do not forget to update filename for inp4PLS.pathfnameTP4Val
             cd(path_prev);
         else % deal with Ludm is empty
             disp('continue wo doing anything for now')
             
         end
         
         case 'UDM-ONLY'
             
%              get_OnlyOne_AT(pathTP)
%              inp4PLS.pathfnameTP4Val
          % 'UDM-ONLY' can only run with Tcv
          inp4PLS_2DF.ModelPara_Opm_Scheme='ModelParaOpmBy-Tcv'; % 'UDM-ONLY' can only run with Tcv
%              CurTcvModelParaOpmScheme
             
         case 'OpmPLS-ONLY'
             
             % prepare for  pathTP
             sd_UDM4XRS=AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(inp4PLS_2DF.path_DFd_UDM));
             sd_CS_XRS4OpmPLS_ONLY=AQP_gui_merged__ssds_gt(inp4PLS_2DF.sd_CS_Val_orig,sd_UDM4XRS);
              delete(AQP_gui_merged__get_OnlyOne_AT(pathTP)); % clean out the orig file there which will be wrong for Scv
             path_prev=pwd;
             cd(pathTP);
             AQP_gui_merged__saveAT(sd_CS_XRS4OpmPLS_ONLY);
             cd(path_prev);
             % prepare for inp4PLS.pathfnameTP4Val
             sd_CS_Val_Cur=AQP_gui_merged__ssds(inp4PLS.pathfnameTP4Val);
             sd_Val_alone=AQP_gui_merged__P2T(sd_CS_Val_Cur);
             sd_CS_Val4OpmPLS_ONLY=AQP_gui_merged__ssds_gt(inp4PLS_2DF.sd_CS_Val_orig,sd_Val_alone);
             cd(fileparts(inp4PLS.pathfnameTP4Val));
             delete(inp4PLS.pathfnameTP4Val);
             AQP_gui_merged__saveAT(sd_CS_Val4OpmPLS_ONLY);
             inp4PLS.pathfnameTP4Val=AQP_gui_merged__get_OnlyOne_AT(pwd);% do not forget to update filename for inp4PLS.pathfnameTP4Val
             cd(path_prev);
         case  'Split_OddUDM_EvenXRS'  
             disp('work on Split_UDM')
             sd_UDM4XRS=AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(inp4PLS_2DF.path_DFd_UDM));
             
             out_Sp=AQP_gui_merged__Atrainpk_Split_Odd_Even(sd_UDM4XRS.LAT);
%              out_Sp.SAT_odd
%              out_Sp.SAT_even
             %%%%%%
             LAT_CS_Val_orig= inp4PLS_2DF.sd_CS_Val_orig.LAT;
             %%%%%%
             sd_CS_Split=AQP_gui_merged__ssds_plus(inp4PLS_2DF.sd_CS_Val_orig,AQP_gui_merged__ssds(out_Sp.SAT_odd));
             %%%%%
             sd_CS_XRS4Split=AQP_gui_merged__ssds_gt(sd_CS_Split,AQP_gui_merged__ssds(out_Sp.SAT_even));
             path_prev=pwd;
             cd(pathTP);
             
             delete(AQP_gui_merged__get_OnlyOne_AT(pathTP)); % clean out the orig file there
             AQP_gui_merged__saveAT(sd_CS_XRS4Split);
             cd(path_prev);
             %%%%%
             sd_CS_Val4Split=AQP_gui_merged__ssds_gt(sd_CS_Split,AQP_gui_merged__P2T(AQP_gui_merged__ssds(inp4PLS.pathfnameTP4Val)));
             
             cd(fileparts(inp4PLS.pathfnameTP4Val));
             delete(inp4PLS.pathfnameTP4Val);
             AQP_gui_merged__saveAT(sd_CS_Val4Split);
             
             % do not forget to update filename for inp4PLS.pathfnameTP4Val
             inp4PLS.pathfnameTP4Val=AQP_gui_merged__get_OnlyOne_AT(pwd);% do not forget to update filename for inp4PLS.pathfnameTP4Val
             % do not forget to update filename for inp4PLS.pathfnameTP4Val
             cd(path_prev);

             
         case 'Scv'
             % prepare for PLS_Scv
             %      if isSAME_2Matrix( L_UDM4XRS_Scv.Apred,X_iAna_Scout_CS)
             LAT_CS_Val_orig= inp4PLS_2DF.sd_CS_Val_orig.LAT;
             
             OrigCS.X=          LAT_CS_Val_orig.Atrainpk;
             OrigCS.Y=          cat(1,LAT_CS_Val_orig.PLS.Tset.saConc.Conc);
             OrigCS.cSampleName=LAT_CS_Val_orig.AclabelT;
             
             sd_UDM4XRS=AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(inp4PLS_2DF.path_DFd_UDM));
             
             ScoutCS.X=          sd_UDM4XRS.LAT.Atrainpk;
             ScoutCS.Y=          cat(1,sd_UDM4XRS.LAT.saConc.Conc);
             ScoutCS.cSampleName=sd_UDM4XRS.LAT.AclabelT;
             %%%%%%%%%%%%%%%%%%%%
             % run Scv to generate all_RMSE_PLS_Scv
             inp4Scv.PlsfactorScan=inp4PLS_2DF.PlsfactorScan;
             inp4Scv.Tcv_scheme=inp4PLS_2DF.CrossValidationType;
             
             [all_RMSE_PLS_Scv]=AQP_gui_merged__Scv4all_RMSE_PLS_Scv(OrigCS,ScoutCS,inp4Scv);% run Scv to generate all_RMSE_PLS_Scv
             inp4PLS.all_RMSE_PLS_Scv=all_RMSE_PLS_Scv;% input all_RMSE_PLS_Scv into SVR_PLS_Opm_by_Testset_then_AppliedToPset_MLtool
             
             %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
             %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
             sd_CS_XRS4Scv=AQP_gui_merged__ssds_gt(inp4PLS_2DF.sd_CS_Val_orig,sd_UDM4XRS);
             delete(AQP_gui_merged__get_OnlyOne_AT(pathTP)); % clean out the orig file there which will be wrong for Scv
             path_prev=pwd;
             cd(pathTP);
             AQP_gui_merged__saveAT(sd_CS_XRS4Scv);
             cd(path_prev);
             
         case {'OpmPLS_AND_Add2CS','Both_UDM_Opm'}   
%              disp('work on Both_UDM_Opm')
             
             
             sd_UDM4XRS=AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(inp4PLS_2DF.path_DFd_UDM));
             sd_CS_XRS4Both=AQP_gui_merged__ssds_gt(AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(pathTP)),sd_UDM4XRS);
             path_prev=pwd;
             cd(pathTP);
             
             delete(AQP_gui_merged__get_OnlyOne_AT(pathTP)); % clean out the orig file there
             AQP_gui_merged__saveAT(sd_CS_XRS4Both);
             cd(path_prev);
             
         case 'UDMasCS'
             
             inp4PLS_2DF.ModelPara_Opm_Scheme='ModelParaOpmBy-Tcv'; % 'UDMasCS' can only run with Tcv
             
             sd_UDM4CS=AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(inp4PLS_2DF.path_DFd_UDM));
             sd_CS_Val_Cur=AQP_gui_merged__ssds(inp4PLS.pathfnameTP4Val);
             sd_Val_alone=AQP_gui_merged__P2T(sd_CS_Val_Cur);
             
             sd_CS_UDM_Val=AQP_gui_merged__ssds_gt(sd_UDM4CS,sd_Val_alone);
             
             path_prev=pwd;
             cd(fileparts(inp4PLS.pathfnameTP4Val));
             delete(inp4PLS.pathfnameTP4Val);
             AQP_gui_merged__saveAT(sd_CS_UDM_Val);
             inp4PLS.pathfnameTP4Val=AQP_gui_merged__get_OnlyOne_AT(pwd);% do not forget to update filename for inp4PLS.pathfnameTP4Val
             cd(path_prev);
             % updating XRS folder
             sd_XRS_folder_Cur=AQP_gui_merged__ssds(AQP_gui_merged__get_OnlyOne_AT(pathTP));
             sd_XRS_alone=AQP_gui_merged__P2T(sd_XRS_folder_Cur);
             sd_CS_XRS4UDMasCS=AQP_gui_merged__ssds_gt(sd_UDM4CS,sd_XRS_alone);
             delete(AQP_gui_merged__get_OnlyOne_AT(pathTP));
             cd(pathTP);
             AQP_gui_merged__saveAT(sd_CS_XRS4UDMasCS);
             cd(path_prev);
             
             
         otherwise
             error('CurUDMas not supported')
     end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    inp4PLS=AQP_gui_merged__catstruct(inp4PLS,inp4PLS_2DF);
    
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % settings for running PLS for historical reason !!!
    inp4PLS.run_PLS_yes=1;inp4PLS.run_SVR_yes=0;
    inp4PLS.TP_scheme='Tall_Pall';
    inp4PLS.list_C=[1.0000e-06 1.0000e-05 1.0000e-04 1.0000e-03 0.0100 0.1000 1 10 100];
    inp4PLS.RMSE_thres4OLs=Inf;  % this must be set because historical reason !!!
    inp4PLS.run_OL_analysis_Val_yes=1;% this must be set because historical reason !!!
    inp4PLS.handles='';
    inp4PLS.PP_methods=''; % PP_methods not used inside SVR_PLS_Opm_by_Testset_then_AppliedToPset_MLtool()

    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    if isempty(pathTP)
        pathTP=inp4PLS.pathfnameTP4Val;  % to deal with case that there was no XRS set
    end
    inp4PLS.handles_gui=inp4PLS_2DF.handles_gui;
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    if ~inp4PLS.handles_gui.Val_Exist.Value
    inp4PLS.pathfnameTP4Val='';  % modified by CH to deal with missing Val set, Jan 28, 2020
    end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
 
if isempty(pathTP) && isempty(inp4PLS.pathfnameTP4Val)
pathTP=clistfile_X_P_Val(  AQP_gui_merged__strfind_cstr('wAT2RS_For_PRO', clistfile_X_P_Val))  ;   % deal with only CS+XRS exist but woVal, Jan 4, 2023
end

%=====================================================================
  inp4PLS.cnt= inp4PLS_2DF.cnt;          % add this for locating Beta_etc_FinalModel_~.mat files inside PLS_inside_PLS_predict_ONLY_MLtool

%================================================================================
     OUT_Regressor=AG_SVR_PLS_Opm_by_Testset_then_AppliedToPset_MLtool(pathTP,inp4PLS);
end
