           end
           
       otherwise
           error('Tcv scheme NOT supported')
   end
   
   
   if ~strcmp(Tcv_scheme(3:end),'Residual-Variance-Increase-Limit')
    RMSE=AQP_gui_merged__RMS_error_woNaN(Yest_all,Y);
