                        hpXSmst= plot(wvl_CS_Bef_MGs,LAT_SbS_XSmst.Atrainpk,'c-','linewidth',0.5);
                        out_MN_grids=AQP_gui_merged__plot_vline_stem(wvl_MN);                                                                       % updated Apr 30, 2021 --> plot_vline_stem
