                if length(loc_SbS_plot_ATfile)==1
                    LAT_SbS=load(clistfilename_SbS{loc_SbS_plot_ATfile});
                    figure; hold on;set(gcf,'position',[621.0000   77.6667  839.3333  626.6667]);
                    hpCS= plot(LAT_SbS.Atrainpk','b-','linewidth',0.5);
                    hpVal=  plot(LAT_SbS.Apred','r-','linewidth',0.5);
                    legend([hpCS(1)   hpVal(1) ],{'CS','Val'});
                   sCur_CabXfer_scheme= handles.CabXfer_scheme.String{handles.CabXfer_scheme.Value};
                     title({[   strrep(AQP_gui_merged__find_lastfolder(handles.path_DS),'_','\_') ,'  ',sCur_CabXfer_scheme];[strrep(SbS_Spectra_type,'_','\_')]});
                    ylabel('Spectra');xlabel('wvl');
                    %===========================================
                    try
                    LR=load(fullfile(handles.OUT_Cmp_Results.Path4OUT_cln_AQP_FinalSubfolder,handles.OUT_Cmp_Results.fname_Results_AQP_OUT_cln));
                    catch
                        disp('try to load a shortname Results_~.mat');
                        
                        [clistfilename_out_Results, nfile_out_Results]=AQP_gui_merged__fdir_wildcard_ext_wPath(handles.OUT_Cmp_Results.Path4OUT_cln_AQP_FinalSubfolder,'Results_','mat');
                        if nfile_out_Results==1
                            LR=load(clistfilename_out_Results{1});
                        else
                            warning('can  Not uniquely find Results_~.mat file,  hence can Not show Qres and T2 for CS_Val_CabXfer_PP ');
                            return;
                        end
                        
                    end
                  opmPLSfactor = str2num( LR.OUT_cln.Results4sOpmPLSfactor);
                    out_Qres_T2=AQP_gui_merged__Calc_Qres_T2_AQPlite(LAT_SbS,opmPLSfactor );
                    disp('work on plot LogStdScale Qres and T2');
                    inp4LogStdScale.opmPLSfactor=opmPLSfactor;
                    inp4LogStdScale.sfname=strrep(AQP_gui_merged__fileparts_name_ext(clistfilename_SbS{loc_SbS_plot_ATfile}),'_','\_');
                     inp4LogStdScale.sDSname= strrep(AQP_gui_merged__find_lastfolder(handles.path_DS),'_','\_') ;
                     
                    inp4LogStdScale.plot_Qres_OR_T2='Qres';
                    out_Qres_LogStdScale=AQP_gui_merged__plot_LogStdScale_Qres_T2 (out_Qres_T2,inp4LogStdScale);
                    
                     inp4LogStdScale.plot_Qres_OR_T2='T2';
                    out_T2_LogStdScale=AQP_gui_merged__plot_LogStdScale_Qres_T2 (out_Qres_T2,inp4LogStdScale);
                    %--------------------------------------------------------------
                    out_Qres_LogStdScale.X_QR_T2_T_scaled ;
                    out_Qres_LogStdScale.X_QR_T2_P_scaled ;
                    
                    out_T2_LogStdScale.X_QR_T2_T_scaled ;
                    out_T2_LogStdScale.X_QR_T2_P_scaled ;
                    figure;hold on;set(gcf,'position',1000*[0.3937    0.0423    1.0613    0.6853]);
                    hpT= plot(out_T2_LogStdScale.X_QR_T2_T_scaled,out_Qres_LogStdScale.X_QR_T2_T_scaled,'bO','linewidth',0.5);
                    hpP= plot(out_T2_LogStdScale.X_QR_T2_P_scaled,out_Qres_LogStdScale.X_QR_T2_P_scaled,'g*','linewidth',0.5);
                    AQP_gui_merged__plot_vline(3,'r');AQP_gui_merged__plot_hline(3,'r');
                    legend([hpT hpP],{'CS or Tset','Val or Pset'});
                    xlabel('Hotelling T-square (scaled by StdLog)'); ylabel('Q Residuals (scaled by StdLog)');
                    title([inp4LogStdScale.sfname;{[inp4LogStdScale.sDSname,'   OpmPLSfactor = ',num2str(inp4LogStdScale.opmPLSfactor )]};]);

                    %--------------------------------------------------------------
                    disp('done with plot LogStdScale Qres and T2');
                    %===========================================
                else
                    AQP_gui_merged__disp_with_border('NO appropriate spectra of CS vs Val were found, hence NO plot will be generated');
                end
            end
            
        otherwise
            keyword4SbS_SpectraType='';
            warning on
            warning('SbS_Spectra_type Not supported');
            warning off
    end
    
    
   
    
    
end
    disp('done on plotting spectra in StepbyStep folder');
end


%% ----- from TP_parsing_Extr_Tcv.m -----------------------------------------
function out=TP_parsing_Extr_Tcv(pfn,inp)
% modified from PLS_Tcv
%  outPLS_Tcv_iPf=PLS_Tcv(X_iAna_T_Tcv,Y_iAna_T_Tcv,cSampleName_T_Tcv,inp4Tcv);  % new and fixed
% data parsing based on "appear order"  Not sortnat
% see also:   Atrainpk_parse_AclabelT_subcls    sprintf_pad_zero_prefix 
if false
    
   
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    AQP_gui_merged__cc
    pfn='C:\work\JDSU\Test_Quant_U2U\Siesler_Data\VS0909\OSW\Atrainpketc_saConc_Caffeine_(M1-105)_pp1-1stDerSGFL7[PO2]_pp2-SNV_nvar119_ncls48_nsamp288.mat';
      inp.CurAnaName='Caffeine';
    inp.Tcv_scheme='Odd-Even-Scans' ;                            %  'Odd-Even-Scans'   '1PSSout'   'sqrtNSfolds-Conc'    'Leave-OneConc-Out'
    out=TP_parsing_Extr_Tcv(pfn,inp)
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    L=load(pfn);


Tcv_scheme= inp.Tcv_scheme;
% [X Y  cSampleName]=saConc2XY(L.PLS.Tset.saConc,inp.CurAnaName);
[X Y  cSampleName]=AQP_gui_merged__saConc2XY(L.saConc,inp.CurAnaName);


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
QSample=unique(cSampleName);
QSample_sortnat=AQP_gui_merged__sortnat(QSample);
QSample_appear_order= AQP_gui_merged__unique_appear_order_cstr(cSampleName);

nSample=length(QSample);
if strcmp(Tcv_scheme,'sqrtNSfolds-Conc')
    nFolds=floor(sqrt(nSample));
elseif strcmp(Tcv_scheme,'Leave-OneConc-Out') | strcmp(Tcv_scheme ,'1PSSout')
    nFolds=nSample;
elseif    strcmp(Tcv_scheme,'Odd-Even-Scans')
     nFolds=2;
else
    error(' "Tcv_scheme" Not supported')
end

seq_pad=[1:ceil(nSample/nFolds)*nFolds];
seq_pad(seq_pad>nSample)=NaN;
idx_table=reshape(seq_pad,[nFolds ceil(nSample/nFolds) ]);

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
path_orig=pwd;
tmpcorename=strrep(AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_ext(pfn),'Atrainpketc','_pp1'),'_saConc_','');

tmpfolder4Save=AQP_gui_merged__tmp_folder_rm_mk([tmpcorename,'_',Tcv_scheme,'_ParseTP_Ncomb',num2str(nFolds)],pwd);
cd(tmpfolder4Save);

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
loc_all=AQP_gui_merged__col_always([1:length(Y)]);
oaTP=[];
for iQS=1:nFolds
    
    %%%%%%%%%%%%%%%%%%%%%%%%
    switch Tcv_scheme
        case {'10folds-Conc','5folds-Conc','sqrtNSfolds-Conc'}
            loc4P_in_QSample_appear_order=idx_table(iQS,:);
            loc4P_in_QSample_appear_order(isnan(loc4P_in_QSample_appear_order))='';
            loc_P_iQS=find(ismember(cSampleName,QSample_appear_order(loc4P_in_QSample_appear_order)));
            loc_T_iQS=setdiff(loc_all,loc_P_iQS);
        case {'Leave-OneConc-Out','1PSSout'}   % PSS: Physically Same Sample
           % loc_P_iQS=strmatch(QSample_sortnat{iQS},cSampleName,'exact');
              loc_P_iQS=strmatch(QSample_appear_order{iQS},cSampleName,'exact');
            loc_T_iQS=setdiff(loc_all,loc_P_iQS);
        case 'Odd-Even-Scans'
            loc_P_iQS=AQP_gui_merged__col_always([ iQS:2:length(cSampleName)]);
            loc_T_iQS=setdiff(loc_all,loc_P_iQS);
    end
    
    
    %%%%%%%%%%%%%%%%%%%%%%%%
    X_T_iQS=X(loc_T_iQS,:);
    Y_T_iQS=Y(loc_T_iQS,:);
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    %checking
    if ~strcmp(Tcv_scheme,'Odd-Even-Scans')
        ID4Pi=cSampleName(loc_P_iQS);
        ID4Ti=cSampleName(loc_T_iQS);
        qID4Pi=unique(ID4Pi);
        qID4Ti=unique(ID4Ti);
        TotalNum_qID=length(qID4Pi)+length(qID4Ti);
        if length(unique(cSampleName))~=TotalNum_qID
            error('not all spectra parsed into training vs prediction set in cross validation')
        end
    end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    X_P_iQS=X(loc_P_iQS,:);
    Y_P_iQS=Y(loc_P_iQS,:);
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    LocT_i=loc_T_iQS;
    try
        LATi.RawSpectra.Tset=L.RawSpectra(LocT_i,:);
    end
    LATi.Atrainpk=L.Atrainpk(LocT_i,:);
    LATi.AclassinfoT=L.AclassinfoT(LocT_i);
    LATi.AclabelT=L.AclabelT(LocT_i);
    LATi.PLS.Tset.saConc=L.saConc(LocT_i);
    %%%%%%%%
     LocP_i=loc_P_iQS;
    try
        LATi.RawSpectra.Pset=L.RawSpectra(LocP_i,:);
    end
    LATi.Apred=L.Atrainpk(LocP_i,:);
    LATi.AclassinfoP=L.AclassinfoT(LocP_i);
    LATi.AclabelP=L.AclabelT(LocP_i);
    LATi.PLS.Pset.saConc=L.saConc(LocP_i);
    %%%%%%%%%%
    LATi.clistclslabel=L.clistclslabel;
    try
    LATi.wvl_standardize=L.wvl_standardize;
    end
    %%%%%%%%%%%%
    sdi=AQP_gui_merged__ssds(LATi);
    inp_i.corename=['icomb',sprintf_pad_zero_prefix(iQS,length(num2str(nFolds))),AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_ext(pfn),'Atrainpketc','_nvar')];
    sdi=AQP_gui_merged__saveAT(sdi,inp_i);
    %%%%%%%%%%%%%
    oaTP=[oaTP;sdi];
end
cd(path_orig);
out.oaTP=oaTP;  % object array for TP pairs
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
AQP_gui_merged__done_with_this_function;
end
