    inp4AQP.AnaName=AnaName;  % add following July 23, 2020
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    [clistfilename_XSmst, nfile_XSmst]=AQP_gui_merged__fdir_wildcard_wPath(pwd,'XSmst');
