    end
    cd(path_prev);
    %%%%%%%%%%%%
    try
         
        path_LX_XRS=AQP_gui_merged__tmp_folder_rm_mk('TMP_AQP-LoadXLSX\Trg-XRS',pwd);
        cd(path_LX_XRS);
        inp4LoadXLSX.CS_XRS_Val='XRS'; % 'CS' 'XRS'  'Val' 'UDM'
        % pathfname_XRS_xlsx='C:\work\JDSU\ModelsTransferMLtool\GLS+UDM\ATetc\Brix_CS102_UDM21\XRS_sugarcane_MicroNIR_4Cmp_nsamp30_RefNaN.xlsx';
        pathfname_XRS_xlsx=AQP_gui_merged__get_OnlyOne_XLSX_wPrefix(InpBR.path_XLSX,'XRS_');
        
