%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% inp.DS_type='single_XLSX_folder';
% inp.DS_type='multiple_DSn_MAT_folders';
