        function out= rgbConvert(x)     
        
        try 
            out=AQP_gui_merged__color_CH(x);
        catch
            
             out1=AQP_gui_merged__color_CH(x(1));       
             out=out1*str2num(x(2))/10;       
        end
end
        
        
        
            
