            ModelName=    strrep( AQP_gui_merged__fileparts_name_ext(pathfname_TP),'Atrainpketc_',        [SVMmodelType]);
        catch
            try
                pathfname_TP=  handles.inp.pathfname_TP;    % modified from above line to this, Dec 20, 2022
