next_sf=[prefixkeyword,num2str(next_cnt_num)];
out=AQP_gui_merged__tmp_folder_rm_mk(next_sf,parent_path);
else
out=AQP_gui_merged__tmp_folder_rm_mk([prefixkeyword,'1'],parent_path);
end
end


