out.sdvB_PDS_yes=sdvB_PDS_yes;
% out.nPDS_WinCls=['nPDS=',num2str(length(cstr_locLwin)),'_',clsname_Lwin];                        % revisit this --> "dvB_PDS_yes" for DM, Apr 30, 2024
