function [all_loc_subgrp idx_match]=AQP_gui_merged__find_belong2subgrp(listall,subgrp)
%find the locations of all numbers in listall belong to subgrp
% export sorted result
%e.g. all_loc_subgrp=find_belong2subgrp([1 2 3 1 2 3],[1 2])
%by Chang Hsiung, May 30, 07
% see also find_belong2subgrp_cstr  is_belong2subgrp is_belong2subgrp_cstr
if false
    
    AQP_gui_merged__find_belong2subgrp(2,5)
    %%%%%%%%%%%%%%%%%
    AQP_gui_merged__find_belong2subgrp(2,[5 2])
    %%%%%%%%%%%%%%%%%
    AQP_gui_merged__find_belong2subgrp([2 5],5)
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if ~isempty(subgrp)

[rn cn]=size(listall);
all_loc_subgrp=[];
idx_match=[];
for sgi=AQP_gui_merged__row_vector_ALWAYS(unique(subgrp))
    loc_sgi=find(listall==sgi);
    
  if rn>=cn
    all_loc_subgrp=[all_loc_subgrp;loc_sgi ];  
    
    if ~isempty(loc_sgi)
    TF=logical(1);
    else
    TF=logical(0);    
    end
    idx_match=[idx_match;TF];

  else
    all_loc_subgrp=[all_loc_subgrp,loc_sgi ];  
    
     if ~isempty(loc_sgi)
    TF=logical(1);
    else
    TF=logical(0);    
    end
    idx_match=[idx_match,TF];
    
    
  end

end
