function skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker(targetstring,marker)
% pls use "find_keyword_numeric_AFTER_marker_cstr" instead !!!
%
% updated to be able to handle cstr as input
% this should not be called directly, pls call its main function: "find_keynumber_numeric_AFTER_marker"
%
% find keyword that is numeric AFTER mark (use regexp)
  % output is in string datatype !!!
% See also : find_keyword_numeric_AFTER_marker_cstr find_keyword_between_markers strtok allwords find_keyword_between_markers_wWildCards
  
if false
    
    skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker('T-214_Lib1_P-215_Lib1','T-')
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker('T-214_Lib1_P-215_Lib1','T')
       %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker('T-214_Lib1_P-215_Lib1','P')
       %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker('T-214_Lib1_P-215_Lib1','X')

    
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% switch to "find_keyword_numeric_AFTER_marker_cstr" instead !!!

skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker_cstr(targetstring,marker);
return


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
pat1=[marker,'\D*\d{1}'];
locT1=regexp(targetstring,pat1,'end');


pat2=[marker,'\D*\d+'];
locT2=regexp(targetstring,pat2,'end');

if ischar(targetstring)
    skeyword=targetstring(locT1:locT2);
elseif iscell(targetstring)
    sia=string(targetstring);
   skeyword= double(sia.extractAfter(marker));
else
    error('data type of targetstring Not supported')
end
end


%% ----- from find_keyword_numeric_AFTER_marker_cstr.m ----------------------
function skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker_cstr(targetstring,marker)
% !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
% updated to be able to handle cstr as input
% this version is more general because it can handle both char or cell as input
% updated Aug 8, 2019
% !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
% change output to double datatype !!! Aug 8, 2019
% change output to double datatype !!! Aug 8, 2019
% find keyword that is numeric AFTER mark (use regexp)
%
%
% See also : find_keyword_between_markers strtok allwords find_keyword_between_markers_wWildCards
  
if false
    
    skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker_cstr('T-214_Lib1_P-215_Lib1','T-')
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker_cstr('T-214_Lib1_P-215_Lib1','T')
       %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker_cstr('T-214_Lib1_P-215_Lib1','P')
       %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker_cstr({'T-214_Lib1_P-215_Lib1';'T-214_Lib1_P-215_Lib1'},'P')
 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     skeyword=AQP_gui_merged__find_keyword_numeric_AFTER_marker_cstr({'T-214_Lib1_P-215_Lib1';'T-214_Lib1_X-215_Lib1'},'P')
    
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
pat1=[marker,'\D*\d{1}'];
locT1=regexp(targetstring,pat1,'end');


pat2=[marker,'\D*\d+'];
locT2=regexp(targetstring,pat2,'end');

if ischar(targetstring)
    skeyword=str2num(targetstring(locT1:locT2));% change output to double datatype !!! Aug 8, 2019
    if isempty(skeyword)
        skeyword=NaN;
    end
elseif iscell(targetstring)
    
    % old approach that was wrong
    %     sia=string(targetstring);
    %    skeyword= double(sia.extractAfter(marker));
    
    % newly fixed approach
    skeyword= cellfun(@(x,T1,T2) AQP_gui_merged__str2num_empty2NaN(x,T1,T2),targetstring,locT1,locT2);% change output to double datatype !!! Aug 8, 2019
    
else
    error('data type of targetstring Not supported')
end
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function out=AQP_gui_merged__str2num_empty2NaN(x,T1,T2)
out=str2num(x(T1:T2));
if isempty(out)
    out=NaN;
end
end


