    lastfolder=pathname(all_bs( max(1, end-N+1)   )+1:end);      % if end-N+1 less than 1, use 1
else
    lastfolder=pathname;
end
end


%% ----- from find_last_nonTMP_folder.m -------------------------------------
function out=AQP_gui_merged__find_last_nonTMP_folder()
% alias of find_last_nonTMP_path
% find last "nonTMP directory"
% "TMP directory": case sensitive for "TMP" and must start with "TMP" !!!
% see also find_last_nonTMP_path rmdir_TMP  ILCQ
if false
    
    out=AQP_gui_merged__find_last_nonTMP_folder()
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % cd to first "TMP"
    path_orig=pwd;
    tmp4ILCQ=AQP_gui_merged__tmp_folder_rm_mk('TMP-ILCQ',pwd);
    cd(tmp4ILCQ);
    
    % cd to 2nd layer of "TMP"
    path_orig=pwd;
    tmp4ILCQ=AQP_gui_merged__tmp_folder_rm_mk('TMP-ILCQ',pwd);
    cd(tmp4ILCQ);
    
    % cd back to last nonTMP directory
    cd(AQP_gui_merged__find_last_nonTMP_folder);
    
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
out=AQP_gui_merged__find_last_nonTMP_path;
end


%% ----- from find_last_nonTMP_path.m ---------------------------------------
function out=AQP_gui_merged__find_last_nonTMP_path()
% find last "nonTMP directory" (the main function not alias)
% "TMP directory": case sensitive for "TMP" and must start with "TMP" !!!
% see also find_last_nonTMP_folder rmdir_TMP ILCQ
%-----------------------------------
if false
    
    out=AQP_gui_merged__find_last_nonTMP_path()
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % cd to first "TMP"
    path_orig=pwd;
    tmp4ILCQ=AQP_gui_merged__tmp_folder_rm_mk('TMP-ILCQ',pwd);
    cd(tmp4ILCQ);
    
    % cd to 2nd layer of "TMP"
    path_orig=pwd;
    tmp4ILCQ=AQP_gui_merged__tmp_folder_rm_mk('TMP-ILCQ',pwd);
    cd(tmp4ILCQ);
    
    % cd back to last nonTMP directory
    cd(AQP_gui_merged__find_last_nonTMP_path);
    
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
curPath=pwd;
curPath=strrep(curPath,'\','/');
ceaDir=AQP_gui_merged__strread_delimiter(curPath,'/');
locTMP=strmatch('TMP',ceaDir);
if ~isempty(locTMP)
   out= AQP_gui_merged__strwrite_all_delimiter(ceaDir(1:locTMP(1)-1),'\');
else
  out= curPath; 
    
end
end


%% ----- from find_lastfolder.m ---------------------------------------------
function lastfolder=AQP_gui_merged__find_lastfolder(pathname)
% e.g.
% pathname='G:\work\LACIS-III\G3_allr\allr_U3tset\Load-T-Dir_U3_LACIS-IIIa-G3';lastfolder=find_lastfolder(pathname)
% e.g. replace(lastfolder,'-','_');
if ischar(pathname)
    
    all_bs=find(pathname=='\');
    if length(all_bs)>0
        lastfolder=pathname(all_bs(end)+1:end);
    else
        lastfolder=pathname;
    end
    
elseif iscell(pathname)
    
    lastfolder=cellfun(@(x) AQP_gui_merged__find_lastfolder(x),pathname,'uniformoutput',false);
    
    
    
else
    error('datatype of pathname not supported');
    
end
end


