    for ic=1:length(str_orig)
    eastr_orig=str_orig{ic};
    eastr_new=AQP_gui_merged__fix_underscore(eastr_orig);
    %eastr_new(find(eastr_orig=='_'))='-';
    str_new{ic}=eastr_new;
    end
if size(str_new)~=size(str_orig)
    str_new=str_new';
end
 
else
    str_new=str_orig;
     str_new=AQP_gui_merged__fix_underscore(str_orig);
    %str_new(find(str_orig=='_'))='-';

end
end


%% ----- from fullPathTransformInternal.m -----------------------------------
function [fileOrFolderFullPath] = fullPathTransformInternal(fileOrfolderName)
%FULLPATHTRANSORMINTERNAL Full Path Transform Internal
%   Internal that transforms a filename in its fullpath.
%   Full paths are not modified.
%
%
%   fileOrfolderName is either a file (folder) name, or a cell array of 
%   files (folders) names.
%   fileOrFolderFullPath is either a file (folder) name, or a cell array of 
%   files (folders) full path according to fileOrfolderName.
%
%   Example
%   %Standard usage
%   fullPathTransformInternal('foldername');
%
%   See also winopen, system

%   Author: Michele Scalseggi
%   Email: michele.scalseggi@gmail.com
%   MATLAB Release: R2015b
%   Copyright: 2017
%   Creation date: 2017-04-24
%   Last revision: 2017-04-27

%% Cell case
if iscell(fileOrfolderName)
    fileOrFolderFullPath = cell(size(fileOrfolderName));
    for ii = 1 : numel(fileOrfolderName)
        fileOrFolderFullPath{ii} = ...
            fullPathTransformInternal(fileOrfolderName{ii});
    end
    return;
end



%% Scalar case
%If this is a full path, do nothing
[thisPath, ~, ext] = fileparts(fileOrfolderName);
if ~isempty(thisPath)
    fileOrFolderFullPath = fileOrfolderName;
    return;
end

%If this is a file, use the which function
if ~isempty(ext)
    fileOrFolderFullPath = which(fileOrfolderName);
    return;
end

%If the current folder contains a folder with this name
cdPlusName = fullfile(cd, fileOrfolderName);
if exist(cdPlusName, 'file')
    fileOrFolderFullPath = cdPlusName;
    return;
end

%If the current folder name coincides with this name
if strcmp(cd, fileOrfolderName)
    fileOrFolderFullPath = cd;
    return;
end

%Try to find the folder in the search path
searchList = strsplit(path, pathsep);
cmpList = strcmp(fileOrfolderName, ...
    cellfun(@(x) AQP_gui_merged__filename(x), searchList, ...
    'UniformOutput', false));
idx = find(cmpList, 1);
if idx ~= -1
    fileOrFolderFullPath = searchList{idx};
    return;
else
    fileOrFolderFullPath = '';
    return;
end

end



%Gets the name from its path
