end


%% ----- from generate_random_orthogonal_vectors.m --------------------------
function [v1, v2, v3] = AQP_gui_merged__generate_random_orthogonal_vectors()
% see also: test_Mahal_Rolling_PCA_Random_covariance_matrix
% see also: generate_random_orthogonal_vectors
% see also: creat_3D_Random_covariance_matrix
%---------------------------------------------------------------
% ask ChatGPT : how to create a randomly oriented 3D orthogonal unit vectors in Matlab
% -----------------------------------------------------------------------------------
% see also: test_Mahal_Rolling_PCA_Random_covariance_matrix
%=======================================================================
if false
    
    AQP_gui_merged__cc
    % Example usage:
    [v1, v2, v3] = AQP_gui_merged__generate_random_orthogonal_vectors();
    disp('Vector 1:');
    disp(v1');
    disp('Vector 2:');
    disp(v2');
    disp('Vector 3:');
    disp(v3');
    %  test
    v1'*v2
    v2'*v3
    v1'*v3
    norm(v1)
    norm(v2)
    norm(v3)
    
    
    
end
%---------------------------------------------------------------
%============================================================================
    % Step 1: Generate three random vectors
    v1 = rand(3, 1);
    v2 = rand(3, 1);
    v3 = rand(3, 1);

    % Step 2: Normalize the vectors
    v1 = v1 / norm(v1);
    v2 = v2 / norm(v2);
    v3 = v3 / norm(v3);

    % Step 3: Ensure orthogonality using Gram-Schmidt process
    v2 = v2 - dot(v2, v1) * v1;
    v2 = v2 / norm(v2);

    v3 = v3 - dot(v3, v1) * v1;
    v3 = v3 - dot(v3, v2) * v2;
    v3 = v3 / norm(v3);
end
    
    
% done_with_this_function;


