%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if iscell(cstr1) && iscell(cstr2) && length(cstr1)==length(cstr2)
    
    out=  all(cellfun(@(x,y) strcmp(x,y),cstr1,cstr2));
    if out
        loc_mismatch='';
