      focusCls_iAP=  listCls_iAP(1) ;
      loc_iAP_Tset_focusCls=AQP_gui_merged__find_belong2subgrp(classinfoT, focusCls_iAP);
      loc_onecls_YT=find(YT_orig== focusCls_iAP );
      YT(loc_onecls_YT)=1;
      %     [N d] = size(XP_allCls_sparse);
