       Y1_pred_APs_libsvm_LocalAuto(:,iAP)=decision_values_adjust_LA ;

      end
      
  end   % end of iAP
  %----------------------------------------------------------------------------------------------------
           AQP_gui_merged__disp_with_border(['NmisP libsvm allCls (',  inp.libsvm_kt ,')  = ' ,num2str(NmisP_lib_allCls)]);
