%% ----- from load_SamLibrary.m ---------------------------------------------
function [errorStr, announce] = AQP_gui_merged__load_SamLibrary
%% called by --> CabXfer_Siesler48_MLtool
% Description
%   This function finds and assembles SamLibrary.dll and TextCopy.dll. The
%   location of the files will depend on whether this function is run in an
%   executable or through MATLAB directly. The output is an error string 
%   which will display the return status, indicating where the error 
%   occurred. If there is no error, then it will be empty.

%% Initialize the output
errorStr = [];
announce = false;   % [MERGED 25 Aug 2026] set true only on a FIRST real failure,
                    % so the caller speaks the problem once per session

%% Locate the path containing the dlls
mainPath = [];

%Check if the program is deployed (i.e. running as an exe or from code)
if isdeployed
    if false
        %Obtain a list of all subfolders where this exe resides in the temporary app folder
        startPath = ctfroot;
        errorStr = [errorStr,' Location: ',ctfroot];
        allFoldersSt = genpath(startPath);
        allFoldersCl = textscan(allFoldersSt,'%s','delimiter',';');
        allFolders = allFoldersCl{1};
        
        %Loop through the temporary app folders in search of the dll
        trgtFile = 'SamLibrary.dll';
        for iFolder = 1:length(allFolders)
            D = dir(allFolders{iFolder,1}); D(1:2) = [];
            if any(contains({D(:).name},trgtFile))
                mainPath = allFolders{iFolder,1};
                break;
            end
        end
        if isempty(mainPath)
            errorStr = [errorStr, 'load_SamLibrary: The SamLibrary File cannot be found.'];
            return;
        end
    end % end if false
    
    mainPath = 'C:\work\JDSU\Test_AQP\Tmp4AQPliteEXE';
    
    
else
    
    
    %     mainPath = 'C:\Viavi\MATLAB Sam Files';
    mainPath = 'C:\work\JDSU\Test_AQP\Tmp4AQPliteEXE';
end
samLibPath = fullfile(mainPath,'SamLibrary.dll');

% %Check to ensure TextCopy.dll also exists in the mainPath
% textCopyPath = fullfile(mainPath,'TextCopy.dll');
% if exist(textCopyPath,'file') == 0
%     errorStr = [errorStr,'load_SamLibrary: TextCopy.dll cannot be found.'];
%     return
% end

%% Create net assembly
% [MERGED 25 Aug 2026] Rewritten. The old body looked in exactly ONE place -
% which('SamLibrary.dll') - and when that came back empty NET.addAssembly('')
% threw, whereupon the caller SPOKE the error aloud on every pass. (The
% hard-coded samLibPath computed above was dead code: the live branch never
% used it.) Now four candidate locations are tried, the outcome is cached in a
% persistent for the session, and the caller is told whether this is the first
% failure so the announcement happens once instead of every time.
persistent SAMLIB_STATE
if isempty(SAMLIB_STATE)
    SAMLIB_STATE = struct('done', false, 'err', '');
end
if SAMLIB_STATE.done
    errorStr = SAMLIB_STATE.err;      % already resolved, or already failed - stay quiet
    announce = false;
    return
end

cand = {};
cand{end+1} = which('SamLibrary.dll');                    % anywhere on the MATLAB path
cand{end+1} = samLibPath;                                 % the hard-coded mainPath above
try
    cand{end+1} = fullfile(fileparts(mfilename('fullpath')), 'SamLibrary.dll');  % beside this file
end
cand{end+1} = fullfile(pwd, 'SamLibrary.dll');            % launch / current folder

samLibPath = '';
for iCand = 1:numel(cand)
    if ~isempty(cand{iCand}) && exist(cand{iCand}, 'file') == 2
        samLibPath = cand{iCand};
        break
    end
end

if isempty(samLibPath)
    errorStr = [errorStr, ' load_SamLibrary: SamLibrary.dll not found. ', ...
        'Drop it on the MATLAB path, or beside AQP_gui_merged.m, if .sam output is wanted. ', ...
        'Everything else in the run is unaffected.'];
    SAMLIB_STATE.done = true;
    SAMLIB_STATE.err  = errorStr;
    announce = true;                  % say it once this session, then never again
    return
end

try
    samLib = NET.addAssembly(samLibPath); %#ok<NASGU>
    disp(['load_SamLibrary: loaded ', samLibPath]);
    SAMLIB_STATE.done = true;
    SAMLIB_STATE.err  = '';
catch ex
    errorStr = [errorStr, ' load_SamLibrary: Net.addAssembly failed on ', samLibPath, ...
        ' -- ', ex.message];
    SAMLIB_STATE.done = true;
    SAMLIB_STATE.err  = errorStr;
    announce = true;
    return
end

% try 
%     textCopy = NET.addAssembly(textCopyPath);
% catch ex
%     errorStr = [errorStr, ' load_SamLibrary: Error during Net.addAssembly of TextCopy.dll.'];
%     return;
% end

end


