%% ----- from loc_preprocess.m ----------------------------------------------
function new_x = AQP_gui_merged__loc_preprocess(old_x,recipe)
% extracted from function [result,method] = uNIR_calc_method(spectrum,method)
if false
    
    % c_model --> "HX_1700_AS_SVM_SG2nd.xml"
    % L0.spectrum --> "3% H2O2_1_2013Sep03_1245.xls"
    
    figure;hold on;
    L0=AQP_gui_merged__load_local_try('Mat_before_preproc_test_uNIR.mat');
    tmp_y = L0.spectrum(:);
    c_model = L0.method.model(1);
    plot(tmp_y,'k')
    
    n_pre=1;
    tmp_y = AQP_gui_merged__loc_preprocess(tmp_y,c_model.preprocess(n_pre));
    L1=AQP_gui_merged__load_local_try('Mat_after_1st_preproc_test_uNIR.mat');
    if AQP_gui_merged__isSAME_2Matrix( L1.tmp_y,tmp_y)
        disp('match 1st preprocess');
        plot(tmp_y,'r')
    else
        error('MIS-match 1st preprocess')
    end
    
    
    n_pre=2;
    tmp_y = AQP_gui_merged__loc_preprocess(tmp_y,c_model.preprocess(n_pre));
    L2=AQP_gui_merged__load_local_try('Mat_after_2nd_preproc_test_uNIR.mat');
    
    if AQP_gui_merged__isSAME_2Matrix( L2.tmp_y,tmp_y)
        disp('match 2nd preprocess');
        plot(tmp_y,'g')
    else
        error('MIS-match 2nd preprocess')
    end
    
    legend({'before preprocess','after 1st preprocess','after 2nd preprocess'})
    
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if ~isfield(recipe,'type')
    disp('Unable to preprocess.  No type')
    new_x = old_x;
    return
end

switch lower(recipe.type)
    case 'rtoa',
        new_x = -log10(old_x);
    case {'mean_center','mean center','zero mean'}
        new_x = old_x - mean(old_x);
    case {'normalize_mean'},
        % make the average of x equal one
        new_x = old_x/mean(old_x);
    case 'snv',
        new_x = (old_x - mean(old_x))/std(old_x);
    case {'sg_smooth','sg_0',}
        % ignore poly_order for now -- assume 3
        new_x = AQP_gui_merged__lsq_smooth(old_x,recipe.width);
    case {'sg_1st','sg_1',}
        % ignore poly_order for now -- assume 3
        new_x = AQP_gui_merged__lsq_deriv(old_x,recipe.width);
    case {'sg_2nd','sg_2',}
        % ignore poly_order for now -- assume 3
        new_x = AQP_gui_merged__lsq_dderiv(old_x,recipe.width);
    case {'chop'}
        % subset of wavelengths
        new_x = old_x;
        if isfield(recipe,'start')
            new_x = new_x(recipe.start+1:end);
        end
        if isfield(recipe,'end')
            new_x = new_x(1:end-recipe.end);
        end
    otherwise,
        disp(sprintf('Preprocess %s not yet supported',recipe.type));
        new_x = old_x;
end

return
end

% end


