function [varargout] = od(folder)
%OD Open directories in the system explorer
%   Open the Working Directory
%
%
%   folder is the folder to open. Optional argument.
%   varargout can be either nothing or the folder full path.
%
%   Example
%   %Open the current working directory
%   od;
%
%   Example
%   %Open a directory
%   %Create a new directory and open it
%   mkdir testDir
%   od testDir;
%
%   Example
%   %Open the a folder and get its path
%   mkdir testDir
%   thisFolderPath = od('testDir');
%
%   See also pwd, cd 

%   Author: Michele Scalseggi
%   Email: michele.scalseggi@gmail.com
%   MATLAB Release: R2015b
%   Copyright: 2017
%   Creation date: 2017-04-24
%   Last revision: 2017-04-24

%Check inupt/output arguments
narginchk(0, 1);
nargoutchk(0, 1);

%If the first argument is not defined, use default value
if nargin < 1
    folder = cd;
end

%Open the current working directory
fullPathFolder = openFolderInternal(folder);

%Define optional output argument
if nargout > 0
    varargout{1} = fullPathFolder;
end

end


