%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if isa(pathfname_AT,'struct')
 LAT=pathfname_AT;   
 try
 pathfname_AT=inp.pathfname_AT;
 catch
 pathfname_AT='';    
 end
else
LAT=load(pathfname_AT);
end

% checking if "RawSpectra" exist ?
if isfield(LAT,'RawSpectra') && ~isempty(LAT.RawSpectra)
    if isa(LAT.RawSpectra,'struct') && isfield(LAT.RawSpectra,'Tset')
        allWL_rawSpectra_orig=LAT.RawSpectra.Tset;
    else
        allWL_rawSpectra_orig=LAT.RawSpectra;
    end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % create a new function --> apply_PP_on_RawSpectra , Nov 9, 2022
    if false
        pp1=inp.PP_methods.pp1;
        % for Tset, do not provide "inp" but need to output "out_MSC"
        [rawSpectra_aftPP1 spp1 out_MSC_PP1]=AQP_gui_merged__preprocess_NIR_spectra(allWL_rawSpectra_orig,pp1);     % to deal with MSC, updated Sept 22, 2020
        spp1=inp.PP_methods.pp1;

        pp2=inp.PP_methods.pp2;
        % for Tset, do not provide "inp" but need to output "out_MSC"
        [rawSpectra_aftPP2 spp2 out_MSC_PP2]=AQP_gui_merged__preprocess_NIR_spectra(rawSpectra_aftPP1,pp2);           % to deal with MSC, updated Sept 22, 2020
        spp2=inp.PP_methods.pp2;

        rawSpectra_aftPP=rawSpectra_aftPP2;
    else   % create a new function --> apply_PP_on_RawSpectra , Nov 9, 2022
        [rawSpectra_aftPP   out_alt]=AQP_gui_merged__apply_PP_on_RawSpectra(allWL_rawSpectra_orig,inp);
        rawSpectra_aftPP1=out_alt.rawSpectra_aftPP1;
        pp1=inp.PP_methods.pp1;
        pp2=inp.PP_methods.pp2;
        spp1=inp.PP_methods.pp1;
        spp2=inp.PP_methods.pp2;

    end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    
    if isa(LAT.RawSpectra,'struct')&& isfield(LAT.RawSpectra,'Pset')
        allWL_rawSpectra_orig_Pset=LAT.RawSpectra.Pset;
        if all(isnan(allWL_rawSpectra_orig_Pset(:)))
            disp('Pset''s RawSpectra are all NaN, hence will NOT apply PP, instead just use Apred')
          rawSpectra_aftPP_Pset=LAT.Apred;  
        else
            inp4NIR_PP1.Tset=allWL_rawSpectra_orig;                                                                                                      % to deal with MSC, updated Sept 22, 2020
           try
            inp4NIR_PP1.xref_MSC= out_MSC_PP1.xref_MSC;
           catch
             inp4NIR_PP1.xref_MSC='';  
           end
           % for Pset, need to provide "inp" but do Not need to output "out_MSC"
        [rawSpectra_aftPP1_Pset spp1]=AQP_gui_merged__preprocess_NIR_spectra(allWL_rawSpectra_orig_Pset,pp1,inp4NIR_PP1);         % to deal with MSC, updated Sept 22, 2020
        
            inp4NIR_PP2.Tset=rawSpectra_aftPP1;                                                                                                            % to deal with MSC, updated Sept 22, 2020
            try
            inp4NIR_PP2.xref_MSC= out_MSC_PP2.xref_MSC;   
            catch
             inp4NIR_PP2.xref_MSC='';    
            end
          % for Pset, need to provide "inp" but do Not need to output "out_MSC"
        [rawSpectra_aftPP2_Pset spp2]=AQP_gui_merged__preprocess_NIR_spectra(rawSpectra_aftPP1_Pset,pp2,inp4NIR_PP2);               % to deal with MSC, updated Sept 22, 2020
        rawSpectra_aftPP_Pset=rawSpectra_aftPP2_Pset;
        end
    end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % only handle pp1 and pp2, NOT pp3 !!!
    spp3='';
    
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    if ~isempty(spp3)
        fname4pretreatment=['_pp1-',spp1,'_pp2-',spp2,'_pp3-',spp3];
    else
        fname4pretreatment=['_pp1-',spp1,'_pp2-',spp2];
    end
    %%%%%%%%%%%%%%%%%%%%%%%%%%
    % checking
    if AQP_gui_merged__isSAME_2Matrix(rawSpectra_aftPP,LAT.Atrainpk)
        if  isempty(strfind(AQP_gui_merged__fileparts_name_wo_ext(pathfname_AT),'_pp1-'))&& isempty(strfind(AQP_gui_merged__fileparts_name_wo_ext(pathfname_AT),'_pp2-'))
            fname_new=strrep(AQP_gui_merged__fileparts_name_ext(pathfname_AT),'.mat',[fname4pretreatment,'.mat']);
        else
         fname_new=AQP_gui_merged__fileparts_name_ext(pathfname_AT);
        end
        SAT=LAT;
       
    else
        AQP_gui_merged__disp_with_border('Atrainpk different from RawSpectra after applying current pretreatments');
        
        
        if  ~isempty(strfind(AQP_gui_merged__fileparts_name_ext(pathfname_AT),'{')) && ~isempty(strfind(AQP_gui_merged__fileparts_name_ext(pathfname_AT),'}')) && ~isempty( AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_ext(pathfname_AT),'_pp1-','}') ) 
            % handle the not so common case that spp1 within a curly bracket !!!
            % 
            cur_spp1=AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_ext(pathfname_AT),'_pp1-','}');
            new_spp1=AQP_gui_merged__find_keyword_between_markers(fname4pretreatment,'_pp1-','_');
             fname_new=strrep(AQP_gui_merged__fileparts_name_ext(pathfname_AT),['_pp1-',cur_spp1],['_pp1-',new_spp1]);
            
        else
            
            if  isempty(strfind(AQP_gui_merged__fileparts_name_wo_ext(pathfname_AT),'_pp1-'))&& isempty(strfind(AQP_gui_merged__fileparts_name_wo_ext(pathfname_AT),'_pp2-'))
                fname_new=strrep(AQP_gui_merged__fileparts_name_ext(pathfname_AT),'.mat',[fname4pretreatment,'.mat']);
            else
                fname_new=AQP_gui_merged__remove_keyword_between_markers(AQP_gui_merged__fileparts_name_ext(pathfname_AT),'pp1-','_');
                %fname_new=remove_keyword_between_markers_wlistRHS(fname_new,'pp2-',{'_','.mat'});
                fname_new=AQP_gui_merged__remove_keyword_between_markers_wlistRHS(fname_new,'pp2-',{'_','.mat'},'keepRHS');
                
                fname_new=strrep(fname_new,'__',[fname4pretreatment,'_']);
                
                
            end
        end
        
        
        
        SAT=LAT;
        SAT.Atrainpk=rawSpectra_aftPP;
        try
            SAT.Apred=rawSpectra_aftPP_Pset;
        end
    end
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    
else
    error('RawSpetra Not available')
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% handle the case of PLS, insert rawSpectra_aftPP into saConc
% try
% if (isfield(inp,'Chemo_Method') && strcmp(inp.Chemo_Method,'PLS')) 
% if strcmp(inp.Chemo_Method,'PLS')
    
    if isfield(SAT,'PLS') && length(SAT.Atrainpk(:,1))==length(SAT.PLS.Tset.saConc)
         disp(' this case with SAT.PLS.Tset.saConc or SAT.PLS.Pset.saConc and NOT SAT.saConc will be handled below')
