        if strcmp(pfT,pfP)
        title({[CabXfer_scheme,' :  Mst(',sTSM,')',' ->  Trg(',sPSM,')'];['pp1-',spp1]});

        else
        title([CabXfer_scheme,' :  Mst(',AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_wo_ext(pfT),'(',')'),')',' ->  Trg(',AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_wo_ext(pfP),'(',')'),')']);
        end
        
        
         figure(30);hold on;
        hp30_P=plot(P_prep','c-O');
        hp30_T=plot(T_prep','r-*');
        legend([hp30_P(1) hp30_T(1)],{'Ref P','Ref T'});
       % title(['Ref sets ->  ',remove_underscore(fileparts_name_wo_ext(pfT))]);
        if strcmp(pfT,pfP) 
               title({[CabXfer_scheme,' :  Mst(',sTSM,')',' ->  Trg(',sPSM,')'];['pp1-',spp1]});

        else
       title(['Ref sets',' :  Mst(',AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_wo_ext(pfT),'(',')'),')',' ->  Trg(',AQP_gui_merged__find_keyword_between_markers(AQP_gui_merged__fileparts_name_wo_ext(pfP),'(',')'),')']);
        end
       end
        
