        siaOut=strrep(siaOut,ToBeErased,'');  % erase kw1 too (this should be applied on siaOut_Found)

    
end

out=siaOut.cellstr;
    if ischar(cstr)&& ~isempty(out)
        out=out{1};
    end
end


