    % test when missing kw1 in cstr
    cstr={'Atrainpketc_ABC_DEF_nsamp231_nsampP222.mat'};
    out=AQP_gui_merged__textual_extractBetween_multiple_kw2(cstr,'_pp1-','_')
    
