% --- Merged from file: fileparts_name_ext.m ---
function AQP_gui_merged__filename= AQP_gui_merged__tmp_folder_rm_mk__fileparts_name_ext(file)
% modified by Chang to handle the case when file is cell of str
% June 24, 2016
if iscell(file)
    cfilename=[];
    for ifile=1:length(file)
        [~,NAME,EXT]=fileparts(file{ifile});
        cfilename=[cfilename;{[NAME,EXT]}];
    end
    AQP_gui_merged__filename=cfilename;
    
elseif ischar(file)
    [~,NAME,EXT]=fileparts(file);
    AQP_gui_merged__filename=[NAME,EXT];
    
else
    error('input file should be cell of str or str')
end
end

