     'ForegroundColor'   ,     ForegroundColor                        ,...
               'Value'   ,     0                                      ,...
 'HorizontalAlignment'   ,     'center'                               ,...
              'Enable'   ,     'on'                                   ,...
       'TooltipString'   ,     ''                                     ,...
            'Callback'   ,     ''                                     ,...
           'FontAngle'   ,     'normal'                               ,...
            'FontName'   ,     'fixed-width'                          ,...
            'FontSize'   ,     BaseFontSize*1.5                       ,...              % changed from 0.8 --> 1.5   ( for Run_Populate_PRV_gui , July 6, 2023 )
           'FontUnits'   ,     'points'                               ,...
          'FontWeight'   ,     'bold'                                 ,...
            'UserData'   ,     []                                     ,...
             'Visible'   ,     'on'                                    ...
                    );

% | FINISH UP
set(fige, 'CloseRequestFcn', {@AQP_gui_merged__cb_closefig, fige, 0})
if MultiSelect, set(htog, 'Callback', {@AQP_gui_merged__cb_selectall, opth}); end
