drawnow
uiwait(fige)
theChosen       = [];
theChosenIDX    = []; 
if ishandle(fige)
    if get(fige, 'UserData')
        idx = cell2mat(get(opth, 'Value'));
        if any(idx)
            str = get(opth, 'string');
            theChosen       = str(find(idx));
            theChosenIDX    = find(idx);
        end
    end
    delete(fige)
end
end
