%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
%  CmpR_~ helper suite - added 22 Aug 2026
%  Support for the rewritten Cmp_Results_AQP (N files, mixed CabXfer
%  schemes) and for the x-axis guard that runs BEFORE a new
%  Results_AQP_~.mat is stored into Path4OUT_cln_AQP_FinalSubfolder.
%
%  This whole block is IDENTICAL in AQP_gui.m, Run_AQP.m and Cmp_Results.m.
%  Local functions are file-private, so each file keeps its own copy; when
%  you edit one, paste the same edit into the other two.
%  Nothing here calls outside base MATLAB except warndlg/questdlg.
%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


% ----- defaults for Cmp_Results_AQP ---------------------------------------
function inp=AQP_gui_merged__CmpR_defaults(inp)
if ~isstruct(inp)
    inp=struct;
end
cdef={ 'XTick_order'      , 'as-run' ; ...
       'strict_XTick'     , 0        ; ...
       'split_by_CabXfer' , 1        ; ...
       'markersize'       , 12       ; ...
       'connect_lines'    , 0        ; ...
       'wrap_XTickLabel'  , 1        ; ...
       'grid_yes'         , 1        };
for k=1:size(cdef,1)
    if ~isfield(inp,cdef{k,1}) || isempty(inp.(cdef{k,1}))
        inp.(cdef{k,1})=cdef{k,2};
    end
end
end


% ----- one series per (file x CabXfer_scheme) -----------------------------
function S=AQP_gui_merged__CmpR_build_series(clistfilename_out,inp)
S=[];
for ifile=1:numel(clistfilename_out)
    pfn=clistfilename_out{ifile};
    try
        Li=load(pfn);
    catch
        warning('CmpR:load_failed','could not load --> %s',pfn);
        continue
    end
    if ~isfield(Li,'OUT_cln')
        warning('CmpR:no_OUT_cln','no OUT_cln inside --> %s',pfn);
        continue
    end
    O=Li.OUT_cln(:);
    cXT  =AQP_gui_merged__CmpR_field_cell(O,'cLegendLoop_jLine');
    vRMSE=AQP_gui_merged__CmpR_field_num (O,'Results4sRMSE_Val');
    cXfer=AQP_gui_merged__CmpR_field_cell(O,'CabXfer_scheme');

    [pp,nn,ee]=fileparts(pfn);   %#ok<ASGLU>
    fname=[nn,ee];

    % Spectra_Avg_Method and AnaName are stamped into OUT_cln from 22 Aug 2026
    % on; for older .mat files fall back to the file name (Spectra_Avg only).
    sSA=AQP_gui_merged__CmpR_join_unique(AQP_gui_merged__CmpR_field_cell(O,'Spectra_Avg_Method'));
    sSA=strrep(sSA,'Spectra_Avg_','');
    if isempty(sSA)
        sSA=AQP_gui_merged__CmpR_token_SpectraAvg(fname);
    end
    sAna=AQP_gui_merged__CmpR_join_unique(AQP_gui_merged__CmpR_field_cell(O,'AnaName'));

    uXfer=AQP_gui_merged__CmpR_unique_stable(cXfer);
    if inp.split_by_CabXfer && numel(uXfer)>1
        cgrp=uXfer;                      % one series per scheme inside this file
    else
        cgrp={''};                       % the usual case - a single series
    end

    for g=1:numel(cgrp)
        if isempty(cgrp{g})
            idx=(1:numel(cXT))';
        else
            idx=find(strcmp(cXfer,cgrp{g}));
        end
        [cXT_g,vRMSE_g,ndup]=AQP_gui_merged__CmpR_dedup(cXT(idx),vRMSE(idx));
        if ndup>0
            warning('CmpR:duplicate_XTick', ...
                '%d duplicated x-axis entries in %s (kept the first of each)',ndup,fname);
        end
        s=struct( ...
            'pathfname',pfn, ...
            'fname'    ,fname, ...
            'ifile'    ,ifile, ...
            'cXT'      ,{cXT_g}, ...
            'RMSE'     ,vRMSE_g, ...
            'sXfer'    ,AQP_gui_merged__CmpR_join_unique(cXfer(idx)), ...
            'sSA'      ,sSA, ...
            'sAna'     ,sAna, ...
            'sPP'      ,AQP_gui_merged__CmpR_token_PPanchor(fname), ...
            'sCore'    ,AQP_gui_merged__CmpR_token_core(fname), ...
            'ndup'     ,ndup);
        S=[S;s];
    end
end
end


% ----- pull a char field out of an OUT_cln struct array -------------------
function c=AQP_gui_merged__CmpR_field_cell(O,sfield)
n=numel(O);
c=cell(n,1);
for i=1:n
    v='';
    try
        v=O(i).(sfield);
    end
    if ischar(v)
        c{i}=v;
    elseif iscell(v) && ~isempty(v) && ischar(v{1})
        c{i}=v{1};
    else
        try
            c{i}=char(string(v));
        catch
            c{i}='';
        end
    end
    if isempty(c{i})
        c{i}='';
    end
end
end


% ----- pull a numeric-in-a-string field out of an OUT_cln struct array ----
function v=AQP_gui_merged__CmpR_field_num(O,sfield)
n=numel(O);
v=nan(n,1);
for i=1:n
    try
        x=O(i).(sfield);
        if ischar(x)
            xd=str2double(x);
            if isnan(xd)
                xd=AQP_gui_merged__CmpR_str2num_safe(x);
            end
            x=xd;
        end
        if isempty(x)
            x=NaN;
        end
        v(i)=x(1);
    catch
        v(i)=NaN;
    end
end
end


function x=AQP_gui_merged__CmpR_str2num_safe(s)
x=NaN;
try
    y=str2num(s);   %#ok<ST2NM>
    if ~isempty(y)
        x=y(1);
    end
end
end


% ----- unique, first-appearance order (unique() sorts, which reorders the
%       PP1+PP2 scan and makes two runs look shuffled) ---------------------
function c=AQP_gui_merged__CmpR_unique_stable(c0)
c0=c0(:);
c={};
for i=1:numel(c0)
    if ~any(strcmp(c0{i},c))
        c{end+1,1}=c0{i};   %#ok<AGROW>
    end
end
end


function s=AQP_gui_merged__CmpR_join_unique(c)
cu=AQP_gui_merged__CmpR_unique_stable(c);
cu=cu(~cellfun(@isempty,cu));
s=AQP_gui_merged__CmpR_strjoin(cu,' ');
end


function s=AQP_gui_merged__CmpR_strjoin(c,ssep)
s='';
for i=1:numel(c)
    if i==1
        s=c{i};
    else
        s=[s,ssep,c{i}];   %#ok<AGROW>
    end
end
end


function tf=AQP_gui_merged__CmpR_allsame(c)
tf=true;
for i=2:numel(c)
    if ~isequal(c{i},c{1})
        tf=false;
        return
    end
end
end


% ----- keep the first of any repeated x label ----------------------------
function [c,v,ndup]=AQP_gui_merged__CmpR_dedup(c0,v0)
c0=c0(:);
v0=v0(:);
keep=true(numel(c0),1);
for i=2:numel(c0)
    if any(strcmp(c0{i},c0(1:i-1)))
        keep(i)=false;
    end
end
ndup=sum(~keep);
c=c0(keep);
v=v0(keep);
end


% ----- 'Results_AQP_{ds_Ana}_..._Spectra_Avg_All_{SNV-PP1}.mat' -> 'All' --
function s=AQP_gui_merged__CmpR_token_SpectraAvg(fname)
s='';
smark='Spectra_Avg_';
k=strfind(fname,smark);
if isempty(k)
    return
end
s=fname(k(end)+length(smark):end);
p=strfind(s,'_{');
if ~isempty(p)
    s=s(1:p(1)-1);
end
s=strrep(s,'.mat','');
end


% ----- last '{~-PP1}' / '{~-PP2}' token ----------------------------------
function s=AQP_gui_merged__CmpR_token_PPanchor(fname)
s='';
try
    t=regexp(fname,'\{[^{}]*-PP[12]\}','match');
    if ~isempty(t)
        s=t{end};
    end
end
end


% ----- file name without the 'Results_AQP_' prefix and the '.mat' --------
function s=AQP_gui_merged__CmpR_token_core(fname)
s=fname;
s=strrep(s,'.mat','');
smark='Results_AQP_';
k=strfind(s,smark);
if ~isempty(k)
    s=s(k(1)+length(smark):end);
end
end


% ----- strip the common head and tail so only what differs is left -------
function c=AQP_gui_merged__CmpR_distinct_tails(c0)
c=c0(:);
if numel(c)<2 || AQP_gui_merged__CmpR_allsame(c)
    return
end
nmin=min(cellfun(@numel,c));
% common head
nh=0;
for k=1:nmin
    ch=c{1}(k);
    ok=true;
    for i=2:numel(c)
        if c{i}(k)~=ch
            ok=false;
            break
        end
    end
    if ok
        nh=k;
    else
        break
    end
end
% common tail
nt=0;
for k=1:(nmin-nh)
    ch=c{1}(end-k+1);
    ok=true;
    for i=2:numel(c)
        if c{i}(end-k+1)~=ch
            ok=false;
            break
        end
    end
    if ok
        nt=k;
    else
        break
    end
end
for i=1:numel(c)
    s=c{i}(nh+1:end-nt);
    s=regexprep(s,'^[_\-\+ ]+','');
    s=regexprep(s,'[_\-\+ ]+$','');
    if isempty(s)
        s=c0{i};
    end
    c{i}=s;
end
end


% ----- legend from whatever actually varies across the series ------------
function clegend=AQP_gui_merged__CmpR_build_legend(S)
nS=numel(S);
cAn=cell(nS,1);
cSA=cell(nS,1);
cXf=cell(nS,1);
cPP=cell(nS,1);
cCo=cell(nS,1);
for i=1:nS
    cAn{i}=S(i).sAna;
    cSA{i}=S(i).sSA;
    cXf{i}=S(i).sXfer;
    cPP{i}=S(i).sPP;
    cCo{i}=S(i).sCore;
end
varAn=~AQP_gui_merged__CmpR_allsame(cAn) && ~all(cellfun(@isempty,cAn));
varSA=~AQP_gui_merged__CmpR_allsame(cSA) && ~all(cellfun(@isempty,cSA));
varXf=~AQP_gui_merged__CmpR_allsame(cXf) && ~all(cellfun(@isempty,cXf));
varPP=~AQP_gui_merged__CmpR_allsame(cPP) && ~all(cellfun(@isempty,cPP));
cCoS =AQP_gui_merged__CmpR_distinct_tails(cCo);

clegend=cell(nS,1);
for i=1:nS
    cpart={};
    if varAn && ~isempty(cAn{i})
        cpart{end+1}=['Analyte -->',cAn{i}];   %#ok<AGROW>
    end
    if varSA && ~isempty(cSA{i})
        cpart{end+1}=['Spectra -->',cSA{i}];   %#ok<AGROW>
    end
    if varXf && ~isempty(cXf{i})
        cpart{end+1}=['CabXfer -->',cXf{i}];   %#ok<AGROW>
    end
    if varPP && ~isempty(cPP{i})
        cpart{end+1}=['PP -->',cPP{i}];        %#ok<AGROW>
    end
    if isempty(cpart)
        cpart={cCoS{i}};
    end
    clegend{i}=AQP_gui_merged__CmpR_strjoin(cpart,'  |  ');
end
% still ambiguous ? then bolt the distinct part of the file name on
if numel(unique(clegend))<nS
    for i=1:nS
        clegend{i}=[clegend{i},'  |  ',cCoS{i}];
    end
end
end


% ----- colour/marker cycle; 1 -> 'b*' and 2 -> 'r*' as in the original ---
function [scol,smkr]=AQP_gui_merged__CmpR_style(k)
ccol={'b','r','k','m',[0 0.6 0],'c',[0.85 0.33 0.10],[0.49 0.18 0.56]};
cmkr={'*','o','s','d','^','v','p','h'};
ic=mod(k-1,numel(ccol))+1;
im=mod(floor((k-1)/numel(ccol)),numel(cmkr))+1;
scol=ccol{ic};
smkr=cmkr{im};
end


% ----- title line for what every series has in common -------------------
function s=AQP_gui_merged__CmpR_common_title(S)
nS=numel(S);
cXf=cell(nS,1);
cSA=cell(nS,1);
cAn=cell(nS,1);
for i=1:nS
    cXf{i}=S(i).sXfer;
    cSA{i}=S(i).sSA;
    cAn{i}=S(i).sAna;
end
cpart={};
uAn=AQP_gui_merged__CmpR_unique_stable(cAn(~cellfun(@isempty,cAn)));
if numel(uAn)==1
    cpart{end+1}=['[',uAn{1},']'];
elseif numel(uAn)>1
    cpart{end+1}=['Analyte --> ',AQP_gui_merged__CmpR_strjoin(uAn,' vs '),'  (RMSEP scales differ !)'];
end
uXf=AQP_gui_merged__CmpR_unique_stable(cXf(~cellfun(@isempty,cXf)));
if numel(uXf)==1
    cpart{end+1}=uXf{1};                                   % as before: the shared CabXfer scheme
elseif numel(uXf)>1
    cpart{end+1}=['CabXfer --> ',AQP_gui_merged__CmpR_strjoin(uXf,' vs '),'  (see legend)'];
end
uSA=AQP_gui_merged__CmpR_unique_stable(cSA(~cellfun(@isempty,cSA)));
if numel(uSA)==1
    cpart{end+1}=['Spectra_Avg_',uSA{1}];
end
s=AQP_gui_merged__CmpR_strjoin(cpart,'    ');
end


% ----- readable report of the x-axis gaps -------------------------------
function smsg=AQP_gui_merged__CmpR_report_XTick_gaps(S,Q,cMissing)
smsg=sprintf('x-axis (cLegendLoop_jLine) entries are NOT identical across the compared files.\n');
smsg=[smsg,sprintf('Union used for the x axis has %d entries.\n',numel(Q))];
for i=1:numel(S)
    if isempty(cMissing{i})
        smsg=[smsg,sprintf('  [%d] %s  -->  complete\n',i,S(i).fname)];   %#ok<AGROW>
    else
        smsg=[smsg,sprintf('  [%d] %s  -->  MISSING %d : %s\n', ...
            i,S(i).fname,numel(cMissing{i}),AQP_gui_merged__CmpR_strjoin(cMissing{i}(:)',', '))];   %#ok<AGROW>
    end
end
end


%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
%  x-axis guard - runs BEFORE a new Results_AQP_~.mat is stored into
%  Path4OUT_cln_AQP_FinalSubfolder (see BatchRun_AutoQuant_DA_pipeline)
%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


% ----- x-axis list straight out of the in-memory OUT_cln -----------------
function cXT=AQP_gui_merged__CmpR_xtick_from_OUT_cln(OUT_cln)
cXT={};
try
    cXT=AQP_gui_merged__CmpR_field_cell(OUT_cln(:),'cLegendLoop_jLine');
    cXT=cXT(~cellfun(@isempty,cXT));
end
end


% ----- x-axis list out of a stored Results_AQP_~.mat --------------------
function cXT=AQP_gui_merged__CmpR_xtick_from_matfile(pfn)
cXT={};
try
    L=load(pfn,'OUT_cln');
    if isfield(L,'OUT_cln')
        cXT=AQP_gui_merged__CmpR_xtick_from_OUT_cln(L.OUT_cln);
    end
end
end


% ----- same SET of x entries (order is allowed to differ) ---------------
function tf=AQP_gui_merged__CmpR_same_XTick_set(cA,cB)
uA=sort(AQP_gui_merged__CmpR_unique_stable(cA));
uB=sort(AQP_gui_merged__CmpR_unique_stable(cB));
tf=isequal(uA(:),uB(:));
end


% ----- is this folder compatible with the new run's x axis ? ------------
function [tf,cbad,nchecked]=AQP_gui_merged__CmpR_folder_XTick_compatible(sfolder,cXT_new)
tf=true;
cbad={};
nchecked=0;
if exist(sfolder,'dir')~=7
    return
end
d=dir(fullfile(sfolder,'*Results_AQP*.mat'));
for i=1:numel(d)
    if d(i).isdir
        continue
    end
    cXT_old=AQP_gui_merged__CmpR_xtick_from_matfile(fullfile(sfolder,d(i).name));
    if isempty(cXT_old)
        continue
    end
    nchecked=nchecked+1;
    if ~AQP_gui_merged__CmpR_same_XTick_set(cXT_old,cXT_new)
        tf=false;
        cbad{end+1,1}=d(i).name;   %#ok<AGROW>
    end
end
end


% =========================================================================
% CmpR_check_XTick_before_store
%   Called just before the new Results_AQP_~.mat is copied into
%   Path4OUT_cln_AQP_FinalSubfolder.  Every file already sitting in that
%   folder is compared, entry by entry, against the new run's
%   cLegendLoop_jLine list (typically the PP1+PP2 preprocessing schemes).
%   A folder that mixes two different scheme lists produces a meaningless
%   Compare Results plot, so the mismatch is caught here rather than there.
%
%   inp.policy
%       'divert'      (default) - keep the new file, but put it in a sibling
%                                 folder  <FinalSubfolder>_XTickSet2, _XTickSet3...
%                                 (the first one that is empty or compatible)
%       'ask'                   - questdlg, one of the three below
%       'save-anyway'           - warn only, store it in the same folder
%       'skip'                  - warn and do not store it at all
%
%   out_XTck.dest_folder  folder that should actually be used
%   out_XTck.save_yes     copy the file or not
%   out_XTck.match_yes    x axis agreed with what was already there
%   out_XTck.msg          human readable reason
% =========================================================================
function out_XTck=AQP_gui_merged__CmpR_check_XTick_before_store(sfolder,cXT_new,inp)
out_XTck.dest_folder=sfolder;
out_XTck.save_yes=true;
out_XTck.match_yes=true;
out_XTck.nchecked=0;
out_XTck.cbad={};
out_XTck.msg='';

if nargin<3 || ~isstruct(inp)
    inp=struct;
end
if ~isfield(inp,'policy') || isempty(inp.policy)
    inp.policy='divert';
end
if nargin<2 || isempty(cXT_new)
    out_XTck.msg='new run carries no cLegendLoop_jLine --> x-axis check skipped';
    disp(['[XTick guard] ',out_XTck.msg]);
    return
end

[tf,cbad,nchecked]=AQP_gui_merged__CmpR_folder_XTick_compatible(sfolder,cXT_new);
out_XTck.match_yes=tf;
out_XTck.cbad=cbad;
out_XTck.nchecked=nchecked;

if tf
    if nchecked==0
        out_XTck.msg=sprintf('[XTick guard] first Results_AQP_~.mat in this folder (%d x-axis entries)',numel(AQP_gui_merged__CmpR_unique_stable(cXT_new)));
    else
        out_XTck.msg=sprintf('[XTick guard] x axis matches the %d file(s) already in this folder',nchecked);
    end
    disp(out_XTck.msg);
    return
end

smsg=sprintf(['[XTick guard] the new run does NOT share the x-axis (PP1+PP2 scheme) list\n', ...
    'of %d file(s) already in\n   %s\n   --> %s\n'], ...
    numel(cbad),sfolder,AQP_gui_merged__CmpR_strjoin(cbad(:)',', '));

spolicy=lower(inp.policy);
if strcmp(spolicy,'ask')
    sans='';
    try
        cq={'The new run does NOT share the x-axis (PP1+PP2 scheme) list'; ...
            'of the Results_AQP_~.mat file(s) already in'; ...
            sfolder;''; ...
            'How should this run be stored ?'};
        sans=questdlg(cq,'Compare Results - x-axis mismatch', ...
            'Separate folder','Save anyway','Do not save','Separate folder');
    end
    switch sans
        case 'Save anyway'
            spolicy='save-anyway';
        case 'Do not save'
            spolicy='skip';
        otherwise
            spolicy='divert';
    end
end

switch spolicy
    case 'save-anyway'
        out_XTck.save_yes=true;
        out_XTck.msg=[smsg,'stored in the same folder anyway (policy save-anyway) - Compare Results will draw the union and flag the gaps'];
    case 'skip'
        out_XTck.save_yes=false;
        out_XTck.msg=[smsg,'NOT stored (policy skip) - the .mat stays in the run folder only'];
    otherwise    % 'divert'
        snew=AQP_gui_merged__CmpR_next_XTickSet_folder(sfolder,cXT_new);
        if isempty(snew)
            out_XTck.save_yes=true;
            out_XTck.msg=[smsg,'could not create a sibling folder - stored in the same folder'];
        else
            out_XTck.dest_folder=snew;
            out_XTck.save_yes=true;
            out_XTck.msg=[smsg,'stored in a separate folder instead --> ',snew];
        end
end
disp(out_XTck.msg);
try
    warndlg(out_XTck.msg,'Compare Results - x-axis mismatch');
end
end


% ----- first  <folder>_XTickSet<k>  that is empty or compatible ---------
function snew=AQP_gui_merged__CmpR_next_XTickSet_folder(sfolder,cXT_new)
snew='';
for k=2:99
    scand=[sfolder,'_XTickSet',num2str(k)];
    if exist(scand,'dir')~=7
        [ok,msg]=mkdir(scand);   %#ok<ASGLU>
        if ok
            snew=scand;
        end
        return
    end
    [tf,cbad,nchecked]=AQP_gui_merged__CmpR_folder_XTick_compatible(scand,cXT_new);   %#ok<ASGLU>
    if tf
        snew=scand;
        return
    end
end
end


%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
%  "Compare Results" button - layout and enable/colour state
%  added 22 Aug 2026
%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


% =========================================================================
% CmpR_layout_Cmp_Results_controls
%   Moves the Compare Results pushbutton up, parks the "# results = n" text
%   directly UNDERNEATH it, and doubles that text's font (the .fig carried no
%   explicit FontSize, i.e. the 8 pt default -> 16 pt bold).
%
%   These are the same numbers AQP_gui_fig_patch.m bakes into AQP_gui.fig.
%   Applying them here too means the layout is right even on a .fig that was
%   never patched, and the call is IDEMPOTENT (absolute positions, not
%   relative nudges) so running it twice changes nothing.
%
%   Character units, against the 112 x 32.3 AQP_gui figure:
%       old  Cmp_Results [64.25 4.81 31.38 2.43]   sNumResults [96.00 5.10 14.88 2.14]
%       new  Cmp_Results [78.00 7.55 31.38 2.60]   sNumResults [78.00 4.90 31.38 2.40]
%   x=78 clears Lines_Xticks (which ends at x=75) at the button's new height.
%   Edit the four vectors below if a different AQP_gui.fig variant (PU / CM /
%   PC / EG / lite) needs another arrangement.
% =========================================================================
function AQP_gui_merged__CmpR_layout_Cmp_Results_controls(handles)
pos_Cmp_Results=[78.00 7.55 31.38 2.60];
pos_sNumResults=[78.00 4.90 31.38 2.40];
FontSize_sNumResults=16;
try
    hB=handles.Cmp_Results;
    hN=handles.sNumResults;
catch
    return
end
try
    set(hB,'Units','characters');
    set(hB,'Position',pos_Cmp_Results);
end
try
    set(hN,'Units','characters');
    set(hN,'Position',pos_sNumResults);
    set(hN,'FontUnits','points','FontSize',FontSize_sNumResults, ...
        'FontWeight','bold','HorizontalAlignment','center');
end
end


% =========================================================================
% CmpR_update_Cmp_Results_button
%   n  = 0 or 1  -> visible, grey, INACTIVE  (there is nothing to compare)
%   n >= 2       -> visible, GREEN, active
%   Also rewrites the "# results = n" label so the number and the button
%   state can never disagree.
%
%   n is taken from nOpt when the caller already counted (Run AQP does), and
%   otherwise recounted from
%   handles.OUT_Cmp_Results.Path4OUT_cln_AQP_FinalSubfolder - which matters
%   after the x-axis guard diverts a run into a _XTickSet~ folder, since the
%   count then belongs to the folder actually used.
% =========================================================================
function n=AQP_gui_merged__CmpR_update_Cmp_Results_button(handles,nOpt)
n=[];
if nargin>=2 && ~isempty(nOpt) && isnumeric(nOpt)
    n=nOpt(1);
end
if isempty(n)
    n=0;
    try
        sfolder=handles.OUT_Cmp_Results.Path4OUT_cln_AQP_FinalSubfolder;
        if ~isempty(sfolder) && exist(sfolder,'dir')==7
            d=dir(fullfile(sfolder,'*Results_AQP*.mat'));
            if ~isempty(d)
                n=sum(~[d.isdir]);
            end
        end
    end
end
% ---- keep the label in step with the state ----------------------------
sNCR='';
try
    sNCR=get(handles.sNumResults,'String');   % get/set, not dot-indexing: works on a plain handle too
end
if iscell(sNCR)
    if isempty(sNCR)
        sNCR='';
    else
        sNCR=sNCR{1};
    end
end
k=strfind(sNCR,'=');
if ~isempty(k)
    sHead=strtrim(sNCR(1:k(1)-1));
else
    sHead=strtrim(sNCR);
end
if isempty(sHead)
    sHead='# results';
end
try
    set(handles.sNumResults,'String',[sHead,' = ',num2str(n)]);
end
% ---- the button ------------------------------------------------------
try
    hB=handles.Cmp_Results;
    set(hB,'Visible','on');
    if n>=2
        set(hB,'Enable','on', ...
            'BackgroundColor',[0.40 0.80 0.40], ...
            'ForegroundColor',[0 0 0], ...
            'TooltipString',sprintf('Compare the %d Results_AQP_~.mat files in the results folder',n));
    else
        set(hB,'Enable','off', ...
            'BackgroundColor',[0.83 0.83 0.83], ...
            'ForegroundColor',[0.45 0.45 0.45], ...
            'TooltipString','Needs at least two Results_AQP_~.mat files in one folder');
    end
end
% ---- the two companion buttons: nothing to show or clear at n=0 -------
if n>=1
    sEn='on';
else
    sEn='off';
end
try
    set(handles.ShowResults,'Enable',sEn);
end
try
    set(handles.ClearResults,'Enable',sEn);
end
end


%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
%  multi-line x tick labels that actually render
%  added 22 Aug 2026
%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


% =========================================================================
% CmpR_set_XTickLabel_wrap
%   Rotated x tick labels with 'PP1+PP2' broken onto two lines.
%
%   WHY THIS EXISTS.  set_XTickLabel has forced
%   TickLabelInterpreter='none' since Apr 2024.  Every caller that had been
%   preparing labels the tex way - strrep('_','\_') and strrep('+','\newline')
%   - has been printing those escapes VERBATIM ever since, e.g.
%       1stDerSGFL7[PO2]\newlineSNV
%   And the obvious repair, a real newline char with interpreter 'none',
%   does not work either: the label is truncated at the newline, so only
%   '1stDerSGFL7[PO2]' survives.
%
%   So this helper goes back to what demonstrably worked - the tex
%   interpreter and a literal \newline - and makes it safe by escaping the
%   tex-special characters in each piece FIRST ( _ ^ { } ), which is what
%   made interpreter 'none' attractive in the first place.  Underscores and
%   {PRO} therefore print as themselves AND the labels wrap.
%
%   inp.wrap_yes  1 (default) split on '+' | 0 one line per label
%
%   NOTE: a label containing a literal backslash is left alone (tex would
%   need \backslash); no PP scheme name has one.
% =========================================================================
function AQP_gui_merged__CmpR_set_XTickLabel_wrap(hax,cLab,deg,fs,inp)
if nargin<5 || ~isstruct(inp)
    inp=struct;
end
if ~isfield(inp,'wrap_yes') || isempty(inp.wrap_yes)
    inp.wrap_yes=1;
end
if ~iscell(cLab)
    cLab={cLab};
end
cLab=cLab(:);
n=numel(cLab);
sNL=char(1);     % private placeholder for "break the line here"
c=cell(n,1);
for i=1:n
    s=cLab{i};
    if ~ischar(s)
        try
            s=char(string(s));
        catch
            s='';
        end
    end
    if inp.wrap_yes
        s=strrep(s,'{PRO}',[sNL,'               MN-PRO']);   % kept from the original summary plot
        s=strrep(s,'+',sNL);
    end
    cpart=AQP_gui_merged__CmpR_split_char(s,sNL);
    for k=1:numel(cpart)
        cpart{k}=AQP_gui_merged__CmpR_tex_escape(cpart{k});
    end
    c{i}=AQP_gui_merged__CmpR_strjoin(cpart,'\newline');
end
try
    set(hax,'TickLabelInterpreter','tex');   % NOT 'none' - see the note above
end
set(hax,'XTick',1:n,'XTickLabel',c,'XTickLabelRotation',deg,'fontsize',fs);
end


function s=AQP_gui_merged__CmpR_tex_escape(s)
s=strrep(s,'_','\_');
s=strrep(s,'^','\^');
s=strrep(s,'{','\{');
s=strrep(s,'}','\}');
end


function c=AQP_gui_merged__CmpR_split_char(s,ch)
c={};
k=strfind(s,ch);
i0=1;
for i=1:numel(k)
    c{end+1,1}=s(i0:k(i)-1);   %#ok<AGROW>
    i0=k(i)+1;
end
c{end+1,1}=s(i0:end);
end


%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
%  "show" and "clear" companions to the Compare Results button
%  added 22 Aug 2026
%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


% =========================================================================
% CmpR_create_Results_buttons
%   Adds two pushbuttons next to Compare Results:
%     Show Results   -> list the Results_AQP_~.mat files in the results
%                       folder to the COMMAND WINDOW
%     Clear Results  -> delete them all (with a confirmation), then refresh
%                       "# results = n" and the Compare Results button
%
%   Created in code rather than in the .fig so their callbacks can be plain
%   function handles to local functions - no GUIDE callback strings, no .fig
%   surgery.  Idempotent: an existing pair is reused, so a second AQP_gui
%   session or a second call adds nothing.
%
%   handles must be committed by the caller (AQP_gui_OpeningFcn does the
%   guidata right after).
% =========================================================================
function handles=AQP_gui_merged__CmpR_create_Results_buttons(handles)
pos_ShowResults =[63.00 6.30 14.50 1.70];
pos_ClearResults=[63.00 4.40 14.50 1.70];
FontSize_buttons=9;
try
    hfig=ancestor(handles.Cmp_Results,'figure');
catch
    return
end
if isempty(hfig) || ~ishandle(hfig)
    return
end
% ---- Show Results ----------------------------------------------------
if ~isfield(handles,'ShowResults') || ~ishandle(handles.ShowResults)
    handles.ShowResults=uicontrol(hfig,'Style','pushbutton', ...
        'Tag','ShowResults','String','Show Results', ...
        'Units','characters','Position',pos_ShowResults, ...
        'FontUnits','points','FontSize',FontSize_buttons, ...
        'TooltipString','List the Results_AQP_~.mat files of the results folder in the command window', ...
        'Callback',@AQP_gui_merged__CmpR_ShowResults_Callback);
else
    set(handles.ShowResults,'Units','characters','Position',pos_ShowResults);
end
% ---- Clear Results ---------------------------------------------------
if ~isfield(handles,'ClearResults') || ~ishandle(handles.ClearResults)
    handles.ClearResults=uicontrol(hfig,'Style','pushbutton', ...
        'Tag','ClearResults','String','Clear Results', ...
        'Units','characters','Position',pos_ClearResults, ...
        'FontUnits','points','FontSize',FontSize_buttons, ...
        'ForegroundColor',[0.60 0 0], ...
        'TooltipString','DELETE every Results_AQP_~.mat in the results folder', ...
        'Callback',@AQP_gui_merged__CmpR_ClearResults_Callback);
else
    set(handles.ClearResults,'Units','characters','Position',pos_ClearResults);
end
end


function AQP_gui_merged__CmpR_ShowResults_Callback(hObject,eventdata)   %#ok<INUSD>
handles=guidata(hObject);
AQP_gui_merged__CmpR_list_Results_files(handles);
end


function AQP_gui_merged__CmpR_ClearResults_Callback(hObject,eventdata)   %#ok<INUSD>
handles=guidata(hObject);
AQP_gui_merged__CmpR_clear_Results_files(handles);
end


% ----- the results folder of the last run, '' when there is none --------
function sfolder=AQP_gui_merged__CmpR_results_folder(handles)
sfolder='';
try
    sfolder=handles.OUT_Cmp_Results.Path4OUT_cln_AQP_FinalSubfolder;
end
if ~ischar(sfolder)
    sfolder='';
end
end


% =========================================================================
% CmpR_list_Results_files  -  what is in the comparison folder right now
% =========================================================================
function [clistfilename_out,n]=AQP_gui_merged__CmpR_list_Results_files(handles)
clistfilename_out={};
n=0;
sfolder=AQP_gui_merged__CmpR_results_folder(handles);
disp('=======================================================================');
if isempty(sfolder)
    disp('Results_AQP_~.mat  -->  no results folder yet (press Run AQP first)');
    disp('=======================================================================');
    return
end
disp(['Results_AQP_~.mat  -->  ',sfolder]);
disp('-----------------------------------------------------------------------');
if exist(sfolder,'dir')~=7
    disp('   ( that folder does not exist any more )');
    disp('=======================================================================');
    return
end
d=dir(fullfile(sfolder,'*Results_AQP*.mat'));
for i=1:numel(d)
    if d(i).isdir
        continue
    end
    n=n+1;
    clistfilename_out{n,1}=fullfile(sfolder,d(i).name);   %#ok<AGROW>
    cXT=AQP_gui_merged__CmpR_xtick_from_matfile(clistfilename_out{n,1});
    disp(['  [',num2str(n),'] ',d(i).name]);
    disp(['        ',num2str(round(d(i).bytes/1024)),' kB   ',d(i).date, ...
        '   x-axis entries: ',num2str(numel(AQP_gui_merged__CmpR_unique_stable(cXT)))]);
end
if n==0
    disp('  ( none )');
end
disp('-----------------------------------------------------------------------');
disp(['  # results = ',num2str(n)]);
disp('=======================================================================');
AQP_gui_merged__CmpR_update_Cmp_Results_button(handles,n);
end


% =========================================================================
% CmpR_clear_Results_files  -  empty the comparison folder
%   Deletes only *Results_AQP*.mat, and only in the folder of the last run -
%   never in the _XTickSet~ siblings, and never the copy that stays in the
%   run folder itself.  Always asks first - and if the dialog cannot be
%   raised at all it CANCELS rather than deletes.  inp.ask_yes=0 skips the
%   question, for scripted use only.
% =========================================================================
function n=AQP_gui_merged__CmpR_clear_Results_files(handles,inp)
if nargin<2 || ~isstruct(inp)
    inp=struct;
end
if ~isfield(inp,'ask_yes') || isempty(inp.ask_yes)
    inp.ask_yes=1;      % the pushbutton always asks; pass 0 to script it
end
n=0;
sfolder=AQP_gui_merged__CmpR_results_folder(handles);
if isempty(sfolder) || exist(sfolder,'dir')~=7
    disp('[clear results] no results folder yet (press Run AQP first)');
    try
        warndlg('There is no results folder yet - press Run AQP first.','Clear Results');
    end
    AQP_gui_merged__CmpR_update_Cmp_Results_button(handles,0);
    return
end
d=dir(fullfile(sfolder,'*Results_AQP*.mat'));
d=d(~[d.isdir]);
nfound=numel(d);
if nfound==0
    disp(['[clear results] nothing to delete in --> ',sfolder]);
    AQP_gui_merged__CmpR_update_Cmp_Results_button(handles,0);
    return
end
if inp.ask_yes
    sans='Cancel';      % if questdlg cannot be raised, do NOT delete
    try
        sans=questdlg({sprintf('Delete all %d Results_AQP_~.mat file(s) in',nfound); ...
            sfolder;'';'This cannot be undone.'}, ...
            'Clear Results','Delete','Cancel','Cancel');
    end
else
    sans='Delete';
end
if ~strcmp(sans,'Delete')
    disp('[clear results] cancelled');
    AQP_gui_merged__CmpR_update_Cmp_Results_button(handles);
    return
end
disp('=======================================================================');
disp(['[clear results] deleting from --> ',sfolder]);
for i=1:nfound
    pfn=fullfile(sfolder,d(i).name);
    try
        delete(pfn);
        disp(['   deleted  ',d(i).name]);
    catch ME_del
        warning('CmpR:delete_failed','could not delete %s (%s)',d(i).name,ME_del.message);
    end
end
n=AQP_gui_merged__CmpR_update_Cmp_Results_button(handles);   % rewrites "# results = n" and greys the button
disp(['[clear results] # results = ',num2str(n)]);
disp('=======================================================================');
end




% =========================================================================
% [SSDS-LOCAL]  ssds-as-local-functions block  --  generated 24 Aug 2026
%
%   PASTE THIS ENTIRE BLOCK at the END of AQP_gui.m (after the last existing
%   local function).  It removes this file's dependency on the path class
%   ssds.m.
%
%   MATLAB resolves a LOCAL function before a classdef on the path, so
%   ssds.m may stay on the path untouched for the rest of the library.
%
%   Objects become PLAIN STRUCTS with the same 16 field names, so every read
%   of  sd.LAT / sd.pathfname_AT / sd.type_Model / sd.ncls / sd.nvar  keeps
%   working with no edit at all.
%
%   Bodies are lifted VERBATIM from ssds.m lines 180-1631.  Every deviation
%   is tagged [SSDS-LOCAL].  Every function is closed with its own end.
% =========================================================================


% ---------- [SSDS-LOCAL] type test replacing isa(x,'ssds') ----------------
function tf = AQP_gui_merged__is_ssds(x)
    tf = isstruct(x) && numel(x)==1 ...
         && isfield(x,'LAT') && isfield(x,'pathfname_AT') ...
         && isfield(x,'type_Model') && isfield(x,'nvar');
end


% ---------- [SSDS-LOCAL] blank object -------------------------------------
% A classdef gives every unset property a [] default.  A struct does not, so
% all 16 fields are pre-created here.  This keeps fieldnames() order stable
% and keeps every isfield()/try-catch path behaving exactly as before.
function obj = AQP_gui_merged__ssds_blank()
    obj = struct( ...
        'nsamp',[],  'nsampT',[], 'nsampP',[], 'nvar',[], ...
        'ncls',[],   'nclsT',[],  'nclsP',[], ...
        'LAT',[],    'pathfname_AT','', ...
        'fname_AT_barebone_tail','', 'type_Model','', ...
        'AclassinfoMap2LC',[], 'clistclslabel_LC',[], ...
        'AclassinfoT_LC',[],   'AclassinfoP_LC',[], ...
        'Clsfr_Model_subtype','' );
end


% ---------- [SSDS-LOCAL] constructor --------------------------------------
function obj = AQP_gui_merged__ssds(varargin) % By adding this constructor to the class definition, you can create an object in one step:

    % [SSDS-LOCAL] pre-create all 16 fields (classdef gave these [] defaults)
    obj = AQP_gui_merged__ssds_blank();

    % [SSDS-LOCAL] idempotent pass-through.  An already-built ssds struct is
    % NOT an LAT struct, so it must be intercepted before the isstruct()
    % branch below (the old classdef could never hit this case).
    if nargin==1 && AQP_gui_merged__is_ssds(varargin{1})
        obj = varargin{1};
        return
    end
    
    if nargin == 1 
        if ischar(varargin{1})
        LAT=AQP_gui_merged__load_local_try(varargin{1});
        obj.pathfname_AT=varargin{1};
        elseif isstruct(varargin{1})
        LAT= varargin{1};  
        obj.pathfname_AT='';
        else
            error('datatype for input not supported')
        end
        obj.nsamp=length(LAT.Atrainpk(:,1));
        obj.nsampT=length(LAT.Atrainpk(:,1));
        
        try
        obj.nsampP=length(LAT.Apred(:,1));
        catch
        obj.nsampP=NaN;    
        end
        %%%%%%
        try
            try
                saConc_T=LAT.PLS.Tset.saConc;
            catch
                saConc_T=LAT.saConc;
            end
        catch
            saConc_T='';
        end
        
        try
            saConc_P=LAT.PLS.Pset.saConc;
        catch
            saConc_P='';
        end
        %%%checking size of T and P and assign 
       % if length(saConc_T)>0 & length(saConc_T)==obj.nsampT
       if length(saConc_T)>0 & ~isempty(saConc_T)  % updated July 28, 2020
           obj.type_Model='PLS';
           %------------------------------------------------------
           % check AclabelT vs saConc.SampleName, Apr 18, 2023
           if ~AQP_gui_merged__isSame_AclabelT_SampleName(LAT)
           AQP_gui_merged__Speak_mk('Mismatch between AclabelT_from_saConc vs SAT.AclabelT');
           end
           %-----------------------------------------------------
           % check whether Atrainpk matched with that inside saConc
           
           %                 LAT.Atrainpk(1,:)
           %                 LAT.saConc(1).Atrainpk(1,:)
           
           %====================================
           % add this July 28, 2020
           % see also:   check_and_try_fix_nsamp_inconsistency_ATsaConc ,  nsamp_ATsaConc_wChecking  ,  nsamp_ATsaConc
           [nsamp_T  nsamp_P out_nsamp]=AQP_gui_merged__nsamp_ATsaConc_wChecking(LAT);
           if ~out_nsamp.nsamp_match
               if ~isempty(obj.pathfname_AT)
                   error(['misMatch in nsamp in  -->',AQP_gui_merged__fileparts_name_ext( obj.pathfname_AT )])
               else
                   error(['misMatch in nsamp !!!'])
               end
           else
               disp('nsamp are consistent within this ATsaConc')
           end
           try
               Atrainpk_from_saConc= cat(1,LAT.saConc.Atrainpk);
               disp('check Atrainpk')
               if length(LAT.saConc)~=length(LAT.Atrainpk(:,1))
                   error('mismatch in size of LAT.saConc vs LAT.Atrainpk')
               end
               if ~AQP_gui_merged__isSAME_2Matrix(Atrainpk_from_saConc,LAT.Atrainpk)
                   AQP_gui_merged__Speak_mk('mismatch between "A" train peak vs that in structure array');
                   [lia_T,locb_T] = AQP_gui_merged__ismember_by_rows(LAT.Atrainpk,Atrainpk_from_saConc);
                   loc_rm=find(lia_T==0);
                   error('can not create ssds instance due to mismatch between Atrainpk from LAT vs that from saConc')
                   %Speak_mk('"A" train peak inside structure array will be replaced by external "A" train peak');
                   %                             [LAT.saConc.Atrainpk]=mat2cell_CH_4SAinsert(LAT.Atrainpk,'row');
                   %LAT.saConc=Atrainpk2saConc(LAT.Atrainpk,LAT.saConc);
               end
           catch
               Atrainpk_from_saConc= cat(1,LAT.PLS.Tset.saConc.Atrainpk);
               disp('check Atrainpk')
               if ~AQP_gui_merged__isSAME_2Matrix(Atrainpk_from_saConc,LAT.Atrainpk)
                   AQP_gui_merged__Speak_mk('mismatch between "A" train peak vs that in structure array')
                   [lia_T,locb_T] = AQP_gui_merged__ismember_by_rows(LAT.Atrainpk,Atrainpk_from_saConc);
                   loc_rm=find(lia_T==0);
                   
                   error('can not create ssds instance due to mismatch between Atrainpk from LAT vs that from saConc')
                   
                   %Speak_mk('"A" train peak inside structure array will be replaced by external "A" train peak');
                   %[LAT.PLS.Tset.saConc.Atrainpk]=mat2cell_CH_4SAinsert(LAT.Atrainpk,'row');
               end
           end
           
           %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
           try
               Apred_from_saConc= cat(1,LAT.PLS.Pset.saConc.Atrainpk);
           catch
               Apred_from_saConc='';
           end
           disp('check Apred')
           if ~isempty(Apred_from_saConc)
               if ~AQP_gui_merged__isSAME_2Matrix(Apred_from_saConc,LAT.Apred)
                   AQP_gui_merged__Speak_mk('mismatch between "A" pred vs that in structure array');
                   [lia_P,locb_P] = AQP_gui_merged__ismember_by_rows(LAT.Apred,Apred_from_saConc);
                   loc_rm=find(lia_P==0);
                   error('can not create ssds instance due to mismatch between Apred from LAT vs that from saConc')
                   %Speak_mk('"A" train peak inside structure array will be replaced by external "A" pred');
                   %[LAT.PLS.Pset.saConc.Atrainpk]=mat2cell_CH_4SAinsert(LAT.Apred,'row');
               end
           end
           %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
       else
           obj.type_Model='Clsfr';
       end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
         if length(saConc_P)>0 & length(saConc_P)~=obj.nsampP
             error('mismatch between size of PLS.Pset.saConc vs nsampP')
         end
        %%%%%%
        obj.nvar=length(LAT.Atrainpk(1,:));
        % deal with Label Combination data structure in multi-label SVM
        if  isfield(LAT,'AclassinfoMap2LC') && isfield(LAT,'clistclslabel_LC') && isfield(LAT,'AclassinfoP')
            % deal with Label Combination data structure in multi-label SVM
            obj.ncls=length(LAT.clistclslabel);
            obj.nclsT=length(LAT.clistclslabel);
            obj.nclsP=length(LAT.clistclslabel_LC);
            %------------------------------------------
            obj.AclassinfoMap2LC=LAT.AclassinfoMap2LC;  % add this July 11, 2023
            %--------------------------------------
            if ~isempty(obj.AclassinfoMap2LC) && max(obj.AclassinfoMap2LC(:,2))==obj.nclsP && max(obj.AclassinfoMap2LC(:,1))==obj.nclsT
               
                obj.Clsfr_Model_subtype= 'MLbClsfr';
                obj.AclassinfoMap2LC=LAT.AclassinfoMap2LC;
            else
                obj.Clsfr_Model_subtype='NotValid_MLbClsfr';
                obj.AclassinfoMap2LC=[];
                warning(obj.Clsfr_Model_subtype);
                
            end
            %                     AclassinfoMap2LC
            %                     clistclslabel_LC
            %                     AclassinfoT_LC
            %                     AclassinfoP_LC
            %                     Clsfr_Model_subtype  % MLbClsfr for above case
        else
            obj.ncls=length(LAT.clistclslabel);
            obj.nclsT=length(LAT.clistclslabel);
            obj.nclsP=NaN;
        end
        
        %%%%%%%%%%%%
        % final output of ssds constructor
        obj.LAT=LAT;
        %##############################
        % check if all classes filled in Tset, May 10, 2023
        if strcmp(obj.type_Model,'Clsfr')&& isfield(obj.LAT,'AclassinfoT' )   % add this checking for "AclassinfoT", Sept 8, 2023
            try
                [QclsinfoT NclsinforT]= AQP_gui_merged__unique_count(obj.LAT.AclassinfoT) ;
                if ~isequal(AQP_gui_merged__row_always(QclsinfoT),[1: length(obj.LAT.clistclslabel)] )
                    % warning(['Misssing class(es) in Tset in L_iQS when ith-Fold = ',num2str(iQS)]);
                    % EB
%                             warning(['mismatch in size of QclsinfoT or QclsinfoP vs  clistclslabel , if it is converting Pset to Tset, maybe it is fine ?']);
                 disp(['mismatch in size of QclsinfoT or QclsinfoP vs  clistclslabel , if it is converting Pset to Tset, maybe it is fine ']);
                end
            catch
                 warning(['mismatch in size of QclsinfoT or QclsinfoP vs  clistclslabel , if it is converting Pset to Tset, maybe it is fine ?']);
            end
        else     
            warning('misssing AclassinfoT for "Clsfr" ??');  % add this checking for "AclassinfoT", Sept 8, 2023
        end
        %%%%%%%%%%%%
     %====================
    % add this fname_AT_barebone_tail,  Dec 22, 2022 
    % see for example --> RUN_SVM_linear_wDecVal_CmpClsfr
    %+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    inp4sA.corename='';
    obj_saveAT=AQP_gui_merged__saveAT(obj,inp4sA);
%           fname_AT_barebone_tail=[svar,sncls,snsamp,snsampT,snsampP,'.mat'];
    delete(obj_saveAT.pathfname_AT) ;                       % make some changes here to get rid of that annoying obj_saveAT.pathfname_AT (July 12, 2025)
    obj.fname_AT_barebone_tail=obj_saveAT.fname_AT_barebone_tail;
    %+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
    %====================
        
    else
        error('not ready to handle this case yet')
        
    end
end   % end of ssds constructor
%%%%%%%%%%%%%%%%


% ---------- [SSDS-LOCAL] method: saveAT ----------
function out_obj=AQP_gui_merged__saveAT(obj,inp)
    %         disp('calculate nsamp, ncls, and nvar, then save as Atrainpketc_~.mat');
    %%%%%%%
    obj_orig=obj;
    %%%%%%%%%%%%%
    try
        corename=['_',inp.corename];
    catch
        corename='';
    end
    %%%%%%%
    snsamp=['_nsamp',num2str(obj.nsamp)];
    if ~isnan(obj.nsampP)
        snsampP=['_nsampP',num2str(obj.nsampP)];
        snsampT=['_nsampT',num2str(obj.nsamp)];
        snsamp='';
        
    else
        snsampP='';
        snsampT='';
    end
    
    if strcmp(obj.type_Model,'Clsfr')
        % deal with Label Combination data structure in multi-label SVM
        if ~isnan(obj.nclsP)
         % deal with Label Combination data structure in multi-label SVM   
         sncls=['_nclsT',num2str(obj.ncls),'_nclsP',num2str(obj.nclsP)];   % deal with Label Combination data structure in multi-label SVM
        else
        sncls=['_ncls',num2str(obj.ncls)];
        end
        
        
    else
        %sncls='';
        try
        sncls=['_ncls',num2str(obj.ncls)];
        catch
         sncls='';   
        end
    end
    
    svar=['_nvar',num2str(obj.nvar)];
    %%%%
    if isempty(corename)&& ~isempty(inp.pathfname_AT)
        corename_tmp=AQP_gui_merged__fileparts_name_ext(inp.pathfname_AT);
        corename_tmp=AQP_gui_merged__find_keyword_between_markers(corename_tmp,'Atrainpketc_','.mat');
          fname_AT=['Atrainpketc_',corename_tmp,'.mat']; 
    else
        fname_AT=['Atrainpketc_',corename,svar,sncls,snsamp,snsampT,snsampP,'.mat'];
        fname_AT=strrep(fname_AT,'__','_');
    end
    %%%%
    %====================
    % add this fname_AT_barebone_tail,  Dec 22, 2022 
    fname_AT_barebone_tail=[svar,sncls,snsamp,snsampT,snsampP,'.mat'];% see for example --> RUN_SVM_linear_wDecVal_CmpClsfr
    %====================
    SAT=obj.LAT;
    save(fname_AT,'-struct','SAT');
    disp([pwd,'\',fname_AT,' has been saved !']);
    obj.pathfname_AT=[pwd,'\',fname_AT];  % update property --> pathfname_AT
    obj.fname_AT_barebone_tail=fname_AT_barebone_tail;% add this fname_AT_barebone_tail,  Dec 22, 2022 
    out_obj=obj;
    %%%%%%%%%%%%%
    % try  to delete previously saved pathfname_AT that user did not provide corename
    % added by CH, June 22, 2020
    % updated Mar 7, 2024 by adding --> && strcmp(pwd,fileparts(obj_orig.pathfname_AT))
    if ~isempty(inp.corename) && ~isempty(obj_orig.pathfname_AT) && ~isequal(obj.pathfname_AT,obj_orig.pathfname_AT)  && strcmp(pwd,fileparts(obj_orig.pathfname_AT))
        try
            delete(obj_orig.pathfname_AT);
        end
    end
    %%%%%%%%%%%%%
end %end of "saveAT" method
