% ---------- [SSDS-LOCAL] method: Atrainpk_replace ----------
function out_obj=AQP_gui_merged__Atrainpk_replace(obj,Atrainpk_new)
    % replace Atrainpk into saConc and replace external Atrainpk too
     % % do not forget to reassign obj to LHS of "=" when calling this method from outside !!!
    % see for example: Atrainpk2saConc()
    LATnew=obj.LAT;
    LATnew.Atrainpk=Atrainpk_new;
    try
        LATnew.saConc=AQP_gui_merged__Atrainpk2saConc(Atrainpk_new,LATnew.saConc);
    catch
        LATnew.PLS.Tset.saConc=AQP_gui_merged__Atrainpk2saConc(Atrainpk_new,LATnew.PLS.Tset.saConc);
    end
    out_obj=AQP_gui_merged__ssds(LATnew);
end % end of Atrainpk_replace method
