        else
            InpBR=Run_AQP__Set_cPP1_fromGUI_AQP(handles,InpBR);
        end
    
    else
        % --> AQP_class='lite'
     InpBR.handles_AQP_gui.cPP1=handles.cPP1.String(handles.cPP1.Value);
    %%%%%%%%%%%%%%%%%%%%%
             % deal with sPP1 set to UI control's title i.e. 'PP1'
