%% ----- isDashLine   [AQP_gui.m lines 746-752] ------------------------------------------------
function out=Run_AQP__isDashLine(x)
if length(unique(x))==1 && strcmp(unique(x),'-')
    out=true;
else
    out=false;
end
end


