                           ScanInfoType='saDSn';
                           ScanInfo.data=saDSn;
                           ScanInfo.seq=iXLG;
                           ScanInfo.cDataTag=call_XLabel_Grids;
                           inp4AQP=Run_AQP__Update_inp4AQP_CurLoop(inp4AQP,ScanInfo,ScanInfoType);
