                   %                     inp4AQP=adjust_PlsfactorScan_AQP('',inp4AQP,PlsfactorScan_default);
                   %                 else
                   %                     % for "Load_XLSX_Folder" case, Ludm stored inside "InpBR"
                   %                     inp4AQP=adjust_PlsfactorScan_AQP(InpBR,'',PlsfactorScan_default);
                   %                 end
                   
