                   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
                   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
                   %            Main Function                           %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
                   %
                   if strcmp(InpBR.handles_AQP_gui.Lines_Xticks_picked,'Lines_PP1--Xticks_CabXfer') || strcmp(InpBR.handles_AQP_gui.Lines_Xticks_picked,'Lines_PP1--Xticks_UDM')
                       
                       if isequal(call_XLabel_Grids,cCabXfer_scheme)
