    close all
    [h,p , mean_sqrt_MD2_X1 , mean_sqrt_MD2_X ,h_alt,p_alt,out_irun ] = Run_AQP__test_Mahal_Rolling_PCA_Random_covariance_matrix( bz,dev_X1 ,inp );
