if isnumeric(A)
%     cX=num2cell(repmat(A,[N 1]));
    
     cX=repmat({A},[N 1]);
   
elseif ischar(A)
    cX=repmat({A},[N 1]);
elseif iscell(A) && length(A)==1
    cX=repmat(A,[N 1]);
else
    error('can only handle numeric, char, or single element cell')
end
