function filename= Run_AQP__fileparts_name_wo_ext(file)
% modified by Chang to handle the case when file is cell of str
% June 24, 2016
if iscell(file)
    cfilename=[];
    for ifile=1:length(file)
        [PATHSTR,NAME,EXT]=fileparts(file{ifile});
        cfilename=[cfilename;{NAME}];
    end
    filename=cfilename;
    
