    Run_AQP__find_keyword_between_markers_wlistRHS('afdaf_E1-00176 000_abd.mat','_E1-',{' ','_'} )
    
    Run_AQP__find_keyword_between_markers_wlistRHS('afdaf_E1-00176.mat','_E1-',{' ','_'} )
    
    Run_AQP__find_keyword_between_markers_wlistRHS('afdaf_E1-00176.mat','_E1-',{' ','','_'} )
    
    Run_AQP__find_keyword_between_markers_wlistRHS('afdaf_E1-00176.mat','_E1-',{' ',''} )
    
end

