%   % - Present in GUI and disable Multi-Selection
   [theChosen, theChosenIDX] = Run_AQP__uicellect(theCell, 'Multi', 0); 
%----------------------------------------------------   
% for picking anaylte in CabXferLite
theCell={'Brix';'Pol';'OtherSugarIngredient'};
   [theChosenAna, theChosenIDX] = Run_AQP__uicellect(theCell, 'Multi', 0); 
theChosenAna
%===================================================
theCell={'Brix';'Pol'};
   [theChosenAna, theChosenIDX] = Run_AQP__uicellect(theCell, 'Multi', 0); 
theChosenAna
%===================================================
theCell={'Brix';'Pol';'Protein';'THC'};
   [theChosenAna, theChosenIDX] = Run_AQP__uicellect(theCell, 'Multi', 0); 
theChosenAna
%----------------------------------------------------
%   % - Present in GUI but Change How it Looks
%   when 'MaxPer' larger than half of # of items and less than total # of
%   items, the results are the same, compare the following two examples

   [theChosen, theChosenIDX] = Run_AQP__uicellect(theCell,'MaxPer',13,'RowPix',35,'ColPix',150); 

   [theChosen, theChosenIDX] = Run_AQP__uicellect(theCell,'MaxPer',12,'RowPix',35,'ColPix',150); 
%
