%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
%  CmpR_~ helper suite - added 22 Aug 2026
%  Support for the rewritten Cmp_Results_AQP (N files, mixed CabXfer
%  schemes) and for the x-axis guard that runs BEFORE a new
%  Results_AQP_~.mat is stored into Path4OUT_cln_AQP_FinalSubfolder.
%
%  This whole block is IDENTICAL in AQP_gui.m, Run_AQP.m and Cmp_Results.m.
%  Local functions are file-private, so each file keeps its own copy; when
%  you edit one, paste the same edit into the other two.
%  Nothing here calls outside base MATLAB except warndlg/questdlg.
%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


% ----- defaults for Cmp_Results_AQP ---------------------------------------
function inp=Run_AQP__CmpR_defaults(inp)
if ~isstruct(inp)
    inp=struct;
end
cdef={ 'XTick_order'      , 'as-run' ; ...
       'strict_XTick'     , 0        ; ...
       'split_by_CabXfer' , 1        ; ...
       'markersize'       , 12       ; ...
       'connect_lines'    , 0        ; ...
       'wrap_XTickLabel'  , 1        ; ...
       'grid_yes'         , 1        };
for k=1:size(cdef,1)
    if ~isfield(inp,cdef{k,1}) || isempty(inp.(cdef{k,1}))
        inp.(cdef{k,1})=cdef{k,2};
    end
end
end


% ----- one series per (file x CabXfer_scheme) -----------------------------
function S=Run_AQP__CmpR_build_series(clistfilename_out,inp)
S=[];
for ifile=1:numel(clistfilename_out)
    pfn=clistfilename_out{ifile};
    try
        Li=load(pfn);
    catch
        warning('CmpR:load_failed','could not load --> %s',pfn);
        continue
    end
    if ~isfield(Li,'OUT_cln')
        warning('CmpR:no_OUT_cln','no OUT_cln inside --> %s',pfn);
        continue
    end
    O=Li.OUT_cln(:);
    cXT  =Run_AQP__CmpR_field_cell(O,'cLegendLoop_jLine');
    vRMSE=Run_AQP__CmpR_field_num (O,'Results4sRMSE_Val');
    cXfer=Run_AQP__CmpR_field_cell(O,'CabXfer_scheme');

    [pp,nn,ee]=fileparts(pfn);   %#ok<ASGLU>
    fname=[nn,ee];

    % Spectra_Avg_Method and AnaName are stamped into OUT_cln from 22 Aug 2026
    % on; for older .mat files fall back to the file name (Spectra_Avg only).
    sSA=Run_AQP__CmpR_join_unique(Run_AQP__CmpR_field_cell(O,'Spectra_Avg_Method'));
    sSA=strrep(sSA,'Spectra_Avg_','');
    if isempty(sSA)
        sSA=Run_AQP__CmpR_token_SpectraAvg(fname);
    end
    sAna=Run_AQP__CmpR_join_unique(Run_AQP__CmpR_field_cell(O,'AnaName'));

    uXfer=Run_AQP__CmpR_unique_stable(cXfer);
    if inp.split_by_CabXfer && numel(uXfer)>1
        cgrp=uXfer;                      % one series per scheme inside this file
    else
        cgrp={''};                       % the usual case - a single series
    end

    for g=1:numel(cgrp)
        if isempty(cgrp{g})
            idx=(1:numel(cXT))';
        else
            idx=find(strcmp(cXfer,cgrp{g}));
        end
        [cXT_g,vRMSE_g,ndup]=Run_AQP__CmpR_dedup(cXT(idx),vRMSE(idx));
        if ndup>0
            warning('CmpR:duplicate_XTick', ...
                '%d duplicated x-axis entries in %s (kept the first of each)',ndup,fname);
        end
        s=struct( ...
            'pathfname',pfn, ...
            'fname'    ,fname, ...
            'ifile'    ,ifile, ...
            'cXT'      ,{cXT_g}, ...
            'RMSE'     ,vRMSE_g, ...
            'sXfer'    ,Run_AQP__CmpR_join_unique(cXfer(idx)), ...
            'sSA'      ,sSA, ...
            'sAna'     ,sAna, ...
            'sPP'      ,Run_AQP__CmpR_token_PPanchor(fname), ...
            'sCore'    ,Run_AQP__CmpR_token_core(fname), ...
            'ndup'     ,ndup);
        S=[S;s];
    end
end
end


% ----- pull a char field out of an OUT_cln struct array -------------------
function c=Run_AQP__CmpR_field_cell(O,sfield)
n=numel(O);
c=cell(n,1);
for i=1:n
    v='';
    try
        v=O(i).(sfield);
    end
    if ischar(v)
        c{i}=v;
    elseif iscell(v) && ~isempty(v) && ischar(v{1})
        c{i}=v{1};
    else
        try
            c{i}=char(string(v));
        catch
            c{i}='';
        end
    end
    if isempty(c{i})
        c{i}='';
    end
end
end


% ----- pull a numeric-in-a-string field out of an OUT_cln struct array ----
function v=Run_AQP__CmpR_field_num(O,sfield)
n=numel(O);
v=nan(n,1);
for i=1:n
    try
        x=O(i).(sfield);
        if ischar(x)
            xd=str2double(x);
            if isnan(xd)
                xd=Run_AQP__CmpR_str2num_safe(x);
            end
            x=xd;
        end
        if isempty(x)
            x=NaN;
        end
        v(i)=x(1);
    catch
        v(i)=NaN;
    end
end
end


function x=Run_AQP__CmpR_str2num_safe(s)
x=NaN;
try
    y=str2num(s);   %#ok<ST2NM>
    if ~isempty(y)
        x=y(1);
    end
end
end


% ----- unique, first-appearance order (unique() sorts, which reorders the
%       PP1+PP2 scan and makes two runs look shuffled) ---------------------
function c=Run_AQP__CmpR_unique_stable(c0)
c0=c0(:);
c={};
for i=1:numel(c0)
    if ~any(strcmp(c0{i},c))
        c{end+1,1}=c0{i};   %#ok<AGROW>
    end
end
end


function s=Run_AQP__CmpR_join_unique(c)
cu=Run_AQP__CmpR_unique_stable(c);
cu=cu(~cellfun(@isempty,cu));
s=Run_AQP__CmpR_strjoin(cu,' ');
end


function s=Run_AQP__CmpR_strjoin(c,ssep)
s='';
for i=1:numel(c)
    if i==1
        s=c{i};
    else
        s=[s,ssep,c{i}];   %#ok<AGROW>
    end
end
end


function tf=Run_AQP__CmpR_allsame(c)
tf=true;
for i=2:numel(c)
    if ~isequal(c{i},c{1})
        tf=false;
        return
    end
end
end


% ----- keep the first of any repeated x label ----------------------------
function [c,v,ndup]=Run_AQP__CmpR_dedup(c0,v0)
c0=c0(:);
v0=v0(:);
keep=true(numel(c0),1);
for i=2:numel(c0)
    if any(strcmp(c0{i},c0(1:i-1)))
        keep(i)=false;
    end
end
ndup=sum(~keep);
c=c0(keep);
v=v0(keep);
end


% ----- 'Results_AQP_{ds_Ana}_..._Spectra_Avg_All_{SNV-PP1}.mat' -> 'All' --
function s=Run_AQP__CmpR_token_SpectraAvg(fname)
s='';
smark='Spectra_Avg_';
k=strfind(fname,smark);
if isempty(k)
    return
end
s=fname(k(end)+length(smark):end);
p=strfind(s,'_{');
if ~isempty(p)
    s=s(1:p(1)-1);
end
s=strrep(s,'.mat','');
end


% ----- last '{~-PP1}' / '{~-PP2}' token ----------------------------------
function s=Run_AQP__CmpR_token_PPanchor(fname)
s='';
try
    t=regexp(fname,'\{[^{}]*-PP[12]\}','match');
    if ~isempty(t)
        s=t{end};
    end
end
end


% ----- file name without the 'Results_AQP_' prefix and the '.mat' --------
function s=Run_AQP__CmpR_token_core(fname)
s=fname;
s=strrep(s,'.mat','');
smark='Results_AQP_';
k=strfind(s,smark);
if ~isempty(k)
    s=s(k(1)+length(smark):end);
end
end


% ----- strip the common head and tail so only what differs is left -------
function c=Run_AQP__CmpR_distinct_tails(c0)
c=c0(:);
if numel(c)<2 || Run_AQP__CmpR_allsame(c)
    return
end
nmin=min(cellfun(@numel,c));
% common head
nh=0;
for k=1:nmin
    ch=c{1}(k);
    ok=true;
    for i=2:numel(c)
        if c{i}(k)~=ch
            ok=false;
            break
        end
    end
    if ok
        nh=k;
    else
        break
    end
end
% common tail
nt=0;
for k=1:(nmin-nh)
    ch=c{1}(end-k+1);
    ok=true;
    for i=2:numel(c)
        if c{i}(end-k+1)~=ch
            ok=false;
            break
        end
    end
    if ok
        nt=k;
    else
        break
    end
end
for i=1:numel(c)
    s=c{i}(nh+1:end-nt);
    s=regexprep(s,'^[_\-\+ ]+','');
    s=regexprep(s,'[_\-\+ ]+$','');
    if isempty(s)
        s=c0{i};
    end
    c{i}=s;
end
end


% ----- legend from whatever actually varies across the series ------------
function clegend=Run_AQP__CmpR_build_legend(S)
nS=numel(S);
cAn=cell(nS,1);
cSA=cell(nS,1);
cXf=cell(nS,1);
cPP=cell(nS,1);
cCo=cell(nS,1);
for i=1:nS
    cAn{i}=S(i).sAna;
    cSA{i}=S(i).sSA;
    cXf{i}=S(i).sXfer;
    cPP{i}=S(i).sPP;
    cCo{i}=S(i).sCore;
end
varAn=~Run_AQP__CmpR_allsame(cAn) && ~all(cellfun(@isempty,cAn));
varSA=~Run_AQP__CmpR_allsame(cSA) && ~all(cellfun(@isempty,cSA));
varXf=~Run_AQP__CmpR_allsame(cXf) && ~all(cellfun(@isempty,cXf));
varPP=~Run_AQP__CmpR_allsame(cPP) && ~all(cellfun(@isempty,cPP));
cCoS =Run_AQP__CmpR_distinct_tails(cCo);

clegend=cell(nS,1);
for i=1:nS
    cpart={};
    if varAn && ~isempty(cAn{i})
        cpart{end+1}=['Analyte -->',cAn{i}];   %#ok<AGROW>
    end
    if varSA && ~isempty(cSA{i})
        cpart{end+1}=['Spectra -->',cSA{i}];   %#ok<AGROW>
    end
    if varXf && ~isempty(cXf{i})
        cpart{end+1}=['CabXfer -->',cXf{i}];   %#ok<AGROW>
    end
    if varPP && ~isempty(cPP{i})
        cpart{end+1}=['PP -->',cPP{i}];        %#ok<AGROW>
    end
    if isempty(cpart)
        cpart={cCoS{i}};
    end
    clegend{i}=Run_AQP__CmpR_strjoin(cpart,'  |  ');
end
% still ambiguous ? then bolt the distinct part of the file name on
if numel(unique(clegend))<nS
    for i=1:nS
        clegend{i}=[clegend{i},'  |  ',cCoS{i}];
    end
end
end


% ----- colour/marker cycle; 1 -> 'b*' and 2 -> 'r*' as in the original ---
function [scol,smkr]=Run_AQP__CmpR_style(k)
ccol={'b','r','k','m',[0 0.6 0],'c',[0.85 0.33 0.10],[0.49 0.18 0.56]};
cmkr={'*','o','s','d','^','v','p','h'};
ic=mod(k-1,numel(ccol))+1;
im=mod(floor((k-1)/numel(ccol)),numel(cmkr))+1;
scol=ccol{ic};
smkr=cmkr{im};
end


% ----- title line for what every series has in common -------------------
function s=Run_AQP__CmpR_common_title(S)
nS=numel(S);
cXf=cell(nS,1);
cSA=cell(nS,1);
cAn=cell(nS,1);
for i=1:nS
    cXf{i}=S(i).sXfer;
    cSA{i}=S(i).sSA;
    cAn{i}=S(i).sAna;
end
cpart={};
uAn=Run_AQP__CmpR_unique_stable(cAn(~cellfun(@isempty,cAn)));
if numel(uAn)==1
    cpart{end+1}=['[',uAn{1},']'];
elseif numel(uAn)>1
    cpart{end+1}=['Analyte --> ',Run_AQP__CmpR_strjoin(uAn,' vs '),'  (RMSEP scales differ !)'];
end
uXf=Run_AQP__CmpR_unique_stable(cXf(~cellfun(@isempty,cXf)));
if numel(uXf)==1
    cpart{end+1}=uXf{1};                                   % as before: the shared CabXfer scheme
elseif numel(uXf)>1
    cpart{end+1}=['CabXfer --> ',Run_AQP__CmpR_strjoin(uXf,' vs '),'  (see legend)'];
end
uSA=Run_AQP__CmpR_unique_stable(cSA(~cellfun(@isempty,cSA)));
if numel(uSA)==1
    cpart{end+1}=['Spectra_Avg_',uSA{1}];
end
s=Run_AQP__CmpR_strjoin(cpart,'    ');
end


% ----- readable report of the x-axis gaps -------------------------------
function smsg=Run_AQP__CmpR_report_XTick_gaps(S,Q,cMissing)
smsg=sprintf('x-axis (cLegendLoop_jLine) entries are NOT identical across the compared files.\n');
smsg=[smsg,sprintf('Union used for the x axis has %d entries.\n',numel(Q))];
for i=1:numel(S)
    if isempty(cMissing{i})
        smsg=[smsg,sprintf('  [%d] %s  -->  complete\n',i,S(i).fname)];   %#ok<AGROW>
    else
        smsg=[smsg,sprintf('  [%d] %s  -->  MISSING %d : %s\n', ...
            i,S(i).fname,numel(cMissing{i}),Run_AQP__CmpR_strjoin(cMissing{i}(:)',', '))];   %#ok<AGROW>
    end
end
end


