% ---------- [SSDS-LOCAL] method: Atrainpk_replace ----------
function out_obj=Run_AQP__Atrainpk_replace(obj,Atrainpk_new)
    % replace Atrainpk into saConc and replace external Atrainpk too
     % % do not forget to reassign obj to LHS of "=" when calling this method from outside !!!
    % see for example: Atrainpk2saConc()
    LATnew=obj.LAT;
    LATnew.Atrainpk=Atrainpk_new;
    try
        LATnew.saConc=Run_AQP__Atrainpk2saConc(Atrainpk_new,LATnew.saConc);
    catch
        LATnew.PLS.Tset.saConc=Run_AQP__Atrainpk2saConc(Atrainpk_new,LATnew.PLS.Tset.saConc);
    end
    out_obj=Run_AQP__ssds(LATnew);
end % end of Atrainpk_replace method


% ---------- [SSDS-LOCAL] method: RawSpectra_replace ----------
function out_obj=Run_AQP__RawSpectra_replace(obj,RawSpectra_new)
    % replace RawSpectra into AT objects
    % % do not forget to reassign obj to LHS of "=" when calling this method from outside !!!
    
    LATnew=obj.LAT;
    try
    LATnew.RawSpectra.Tset=RawSpectra_new;
    catch
    LATnew.RawSpectra=RawSpectra_new;   
    end
    out_obj=Run_AQP__ssds(LATnew);
end % end of Atrainpk_replace method


% ---------- [SSDS-LOCAL] operator overloads, renamed ----------------------
% MATLAB operators never consult local functions, so the + and > call sites
% are rewritten:   a+b -> ssds_plus(a,b)     a>b -> ssds_gt(a,b)
function r = Run_AQP__ssds_plus(o1,o2)
    r = Run_AQP__ssds_method_plus(o1,o2);
end

function oTP = Run_AQP__ssds_gt(o1,o2)
    oTP = Run_AQP__TP_pair(o1,o2);
end


% ---------- [SSDS-LOCAL] reachable helper closure folded in from ssds.m ---
% None of these is referenced anywhere else in Run_AQP.m, so folding them in
% shadows nothing Run_AQP.m was already resolving from the path.

% ----- [SSDS-LOCAL] helper: ssds_method_plus -----
function r=Run_AQP__ssds_method_plus(o1,o2)
% see also ssds
% see also : ssds_method_minus
%=====================================================
% add following to deal with case that o2.LAT.clistclslabel is subset of o1.LAT.clistclslabel, Apr 5, 2024
%  see also:cross_units_predict_CARE_fLMVD 
% disp('even not same seq, but can be fix');
