% ----- [SSDS-LOCAL] helper: strcmp_CI_two_cstr -----
function match_table=Run_AQP__strcmp_CI_two_cstr(cstr1,cstr2)
% pls see also findstr_CI_two_cstr.m
match_table=[];
for ic1=1:length(cstr1)
    for ic2=1:length(cstr2)
       if Run_AQP__strcmp_CI(cstr1(ic1),cstr2(ic2))
           match_table(ic1,ic2)=1;
       else
           match_table(ic1,ic2)=0;
       end
    end
end
end


